# builder/gen_ch26_p1.py
# -*- coding: utf-8 -*-

exercises = [{'num': 1, 'title': 'Создание первого обработчика времени с форматом RFC3339', 'task': 'Создай обработчик `/time`, который возвращает текущее время в формате `time.Now().Format(time.RFC3339)`.', 'theory': 'В Go базовый обработчик реализуется через функцию с сигнатурой `func(w http.ResponseWriter, r *http.Request)`. Интерфейс `http.ResponseWriter` используется для отправки заголовков и записи тела ответа клиенту. Стандартный формат `time.RFC3339` (ISO 8601) является общепринятым стандартом передачи временных меток в веб-сервисах и API.', 'step_by_step': '1. Создадим кастомный мультиплексор `mux := http.NewServeMux()`.\n2. Зарегистрируем маршрут `/time` через `mux.HandleFunc`.\n3. В обработчике отформатируем `time.Now()` в RFC3339 и запишем в `w` через `fmt.Fprint` или `w.Write`.\n4. Проверим работу обработчика с помощью `httptest.NewServer`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc timeHandler(w http.ResponseWriter, r *http.Request) {\n\tw.Header().Set("Content-Type", "text/plain; charset=utf-8")\n\tcurrentTime := time.Now().Format(time.RFC3339)\n\tfmt.Fprint(w, currentTime)\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/time", timeHandler)\n\n\tserver := httptest.NewServer(mux)\n\tdefer server.Close()\n\n\tresp, err := http.Get(server.URL + "/time")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Status] %d %s\\n", resp.StatusCode, resp.Status)\n\tfmt.Printf("[Body]   %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status] 200 200 OK\n# [Body]   2026-09-03T13:48:00+04:00'}], 'under_the_hood': 'Когда вызывается `fmt.Fprint(w, ...)`, рантайм `net/http` буферизует запись и, если заголовки еще не были отправлены явно через `WriteHeader`, автоматически вызывает `w.WriteHeader(http.StatusOK)` и вычисляет `Content-Type`, если он не задан.', 'pitfalls': 'Забытый вызов установки `Content-Type` заставляет Go определять MIME-тип с помощью `http.DetectContentType`, что может быть неэффективно или привести к нежелательному типу данных.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в микросервисах временные метки передают исключительно в UTC формате RFC3339/ISO 8601?»\n**Ответ:** Передача локального времени чревата рассинхронизацией из-за переходов на летнее/зимнее время и разных часовых поясов серверов и клиентов. UTC в стандарте RFC3339 однозначно фиксирует момент времени во вселенной без двусмысленности.'}, {'num': 2, 'title': 'Базовый HTTP-сервер Hello World с корневым обработчиком', 'task': 'Запустите HTTP-сервер с одним обработчиком `/`, возвращающим «Hello, World!».', 'theory': 'Корневой паттерн `/` в стандартном `http.ServeMux` до Go 1.22 работал как catch-all префикс: любой путь, для которого не нашлось более точного совпадения, попадал в обработчик `/`. С Go 1.22 точное совпадение корня можно задать как `/{$}` или проверять `r.URL.Path == "/"`, чтобы не отвечать "Hello, World!" на любые случайные URL.', 'step_by_step': '1. Создадим явный роутер `http.NewServeMux()`.\n2. Зарегистрируем функцию для корня `/`.\n3. Добавим проверку пути `if r.URL.Path != "/"` для возврата 404 на сторонние пути.\n4. Отправим запросы к `/` и `/unknown`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc rootHandler(w http.ResponseWriter, r *http.Request) {\n\tif r.URL.Path != "/" {\n\t\thttp.NotFound(w, r)\n\t\treturn\n\t}\n\tfmt.Fprint(w, "Hello, World!")\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/", rootHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\tfmt.Println("[GET /]        Status:", resp.StatusCode, "Body:", string(body))\n\n\tresp404, _ := http.Get(ts.URL + "/something")\n\tresp404.Body.Close()\n\tfmt.Println("[GET /something] Status:", resp404.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [GET /]        Status: 200 Body: Hello, World!\n# [GET /something] Status: 404'}], 'under_the_hood': 'В Go `http.NotFound(w, r)` — это вспомогательная функция, вызывающая `http.Error(w, "404 page not found", http.StatusNotFound)`.', 'pitfalls': 'Если зарегистрировать `mux.HandleFunc("/", ...)` и не проверить `r.URL.Path != "/"`, сервер отдаст 200 OK на любой несуществующий URL (`/api/v1/unknown`, `/favicon.ico` и т.д.).', 'bigtech_interview': '**Вопрос с собеседования:** «Как в Go 1.22+ зарегистрировать строгий корень без catch-all поведения?»\n**Ответ:** Использовать паттерн `mux.HandleFunc("GET /{$}", handler)`. Символ `{$}` в Go 1.22 означает конец пути и запрещает совпадение с дочерними маршрутами.'}, {'num': 3, 'title': 'Реализация интерфейса http.Handler на кастомной структуре', 'task': 'Реализуй интерфейс `http.Handler` на своей структуре (метод `ServeHTTP(w, r)`). Передай эту структуру в `http.ListenAndServe`.', 'theory': 'Интерфейс `http.Handler` — центральный фундамент всей веб-экосистемы Go:\n```go\ntype Handler interface {\n    ServeHTTP(ResponseWriter, *Request)\n}\n```\nЛюбой тип, реализующий метод `ServeHTTP`, может выступать в качестве сервера, роутера или middleware. Реализация интерфейса на структуре позволяет передавать зависимости (БД, кэш, логгеры, конфигурацию) прямо в поля структуры.', 'step_by_step': '1. Объявим структуру `AppServer` с зависимостями (например, `appName` и `version`).\n2. Реализуем метод `ServeHTTP(w http.ResponseWriter, r *http.Request)`.\n3. Передадим экземпляр `&AppServer{}` как главный обработчик.\n4. Протестируем через `httptest.NewServer`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype AppServer struct {\n\tAppName string\n\tVersion string\n}\n\nfunc (s *AppServer) ServeHTTP(w http.ResponseWriter, r *http.Request) {\n\tw.Header().Set("Content-Type", "text/plain; charset=utf-8")\n\tw.WriteHeader(http.StatusOK)\n\tfmt.Fprintf(w, "Сервис: %s, Версия: %s, Путь: %s\\n", s.AppName, s.Version, r.URL.Path)\n}\n\nfunc main() {\n\tapp := &AppServer{\n\t\tAppName: "BillingService",\n\t\tVersion: "v1.4.2",\n\t}\n\n\tts := httptest.NewServer(app)\n\tdefer ts.Close()\n\n\tresp, err := http.Get(ts.URL + "/health")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Print(string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сервис: BillingService, Версия: v1.4.2, Путь: /health'}], 'under_the_hood': '`http.Server` внутри цикла приема соединений `Accept()` запускает горутину `go c.serve(connCtx)` и вызывает `server.Handler.ServeHTTP(w, w.req)`. Если `server.Handler == nil`, используется `http.DefaultServeMux`.', 'pitfalls': 'Экземпляр структуры используется конкурентно всеми входящими горутинами, поэтому поля структуры должны быть неизменяемыми (read-only) либо защищаться мьютексами/атомиками.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему Dependency Injection через структуры с ServeHTTP предпочтительнее глобальных переменных?»\n**Ответ:** Передача зависимостей в поля структуры исключает состояние гонки при параллельном тестировании, позволяет легко подменять зависимости моками в тестах и изолировать несколько экземпляров сервисов с разными конфигурациями в одном процессе.'}, {'num': 4, 'title': 'Множественная маршрутизация: текстовые ответы, системное время и JSON', 'task': 'Добавьте маршруты `/hello`, `/time`, `/json` с разными ответами (текст, текущее время, JSON-структура).', 'theory': 'Современные веб-сервисы отдают различные типы контента. Ключевым требованием является установка корректного заголовка `Content-Type`: `text/plain` для простого текста и `application/json` для сериализованных данных.', 'step_by_step': '1. Создадим `mux := http.NewServeMux()`.\n2. Зарегистрируем `/hello` (отдает `Hello!`).\n3. Зарегистрируем `/time` (отдает RFC3339).\n4. Зарегистрируем `/json` (сериализует структуру через `json.NewEncoder`).\n5. Проверим все три маршрута клиентом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\ntype StatusResponse struct {\n\tStatus  string `json:"status"`\n\tService string `json:"service"`\n\tCode    int    `json:"code"`\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\n\tmux.HandleFunc("/hello", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "text/plain; charset=utf-8")\n\t\tfmt.Fprint(w, "Hello, Gopher!")\n\t})\n\n\tmux.HandleFunc("/time", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "text/plain; charset=utf-8")\n\t\tfmt.Fprint(w, time.Now().UTC().Format(time.RFC3339))\n\t})\n\n\tmux.HandleFunc("/json", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tresp := StatusResponse{Status: "operational", Service: "AuthAPI", Code: 200}\n\t\t_ = json.NewEncoder(w).Encode(resp)\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tfor _, path := range []string{"/hello", "/time", "/json"} {\n\t\tres, _ := http.Get(ts.URL + path)\n\t\tb, _ := io.ReadAll(res.Body)\n\t\tres.Body.Close()\n\t\tfmt.Printf("%-7s | Content-Type: %-25s | Body: %s", path, res.Header.Get("Content-Type"), string(b))\n\t\tif path != "/json" {\n\t\t\tfmt.Println()\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# /hello  | Content-Type: text/plain; charset=utf-8     | Body: Hello, Gopher!\n# /time   | Content-Type: text/plain; charset=utf-8     | Body: 2026-09-03T09:48:00Z\n# /json   | Content-Type: application/json              | Body: {"status":"operational","service":"AuthAPI","code":200}'}], 'under_the_hood': '`json.NewEncoder(w).Encode(v)` пишет сериализованный JSON прямо в сокет `http.ResponseWriter` чанками, не выделяя промежуточный буфер `[]byte` в куче, в отличие от `json.Marshal`.', 'pitfalls': 'Вызов `json.NewEncoder(w).Encode(v)` автоматически добавляет символ перевода строки `\\n` в конец ответа. Устанавливать `Content-Type` нужно строго до вызова `Encode`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между json.Marshal и json.NewEncoder при формировании HTTP-ответа?»\n**Ответ:** `json.Marshal` создает полный срез байтов `[]byte` в куче, что при больших объемах данных создает нагрузку на GC. `json.NewEncoder(w)` реализует потоковую запись прямо в сетевой сокет с минимальным расходом памяти.'}, {'num': 5, 'title': 'Классический запуск HTTP-сервера с ListenAndServe', 'task': 'Напиши простейший HTTP-сервер: `http.HandleFunc("/hello", func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "Hello") })`. Запусти `http.ListenAndServe(":8080", nil)`.', 'theory': 'Функция `http.ListenAndServe(addr, handler)` создает слушающий TCP-сокет на указанном порту и запускает бесконечный цикл `Accept()`. Передача `nil` в качестве второго аргумента заставляет сервер использовать глобальный мультиплексор `http.DefaultServeMux`.', 'step_by_step': '1. Зарегистрируем маршрут `/hello` через глобальный `http.HandleFunc`.\n2. Напишем функцию запуска с проверкой сетевых ошибок.\n3. Продемонстрируем работу сервера.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"time"\n)\n\nfunc main() {\n\thttp.HandleFunc("/hello", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Hello from Standalone Server")\n\t})\n\n\t// Запуск сервера в горутине для демонстрации\n\tgo func() {\n\t\tfmt.Println("[Server] Запуск HTTP-сервера на :8080...")\n\t\tif err := http.ListenAndServe("127.0.0.1:8080", nil); err != nil && err != http.ErrServerClosed {\n\t\t\tfmt.Printf("Ошибка сервера: %v\\n", err)\n\t\t}\n\t}()\n\n\ttime.Sleep(50 * time.Millisecond)\n\n\tresp, err := http.Get("http://127.0.0.1:8080/hello")\n\tif err == nil {\n\t\tdefer resp.Body.Close()\n\t\tfmt.Printf("[Client] Успешное подключение! Статус: %d\\n", resp.StatusCode)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server] Запуск HTTP-сервера на :8080...\n# [Client] Успешное подключение! Статус: 200'}], 'under_the_hood': 'Под капотом `http.ListenAndServe` создает объект `&http.Server{Addr: addr, Handler: handler}` и вызывает его метод `server.ListenAndServe()`.', 'pitfalls': 'В продакшене `http.ListenAndServe` без таймаутов опасен, так как сервер подвержен атакам Slowloris (зависание соединений). Всегда предпочтительнее настраивать `&http.Server{ReadTimeout: ..., WriteTimeout: ...}`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в продакшене не рекомендуется использовать http.DefaultServeMux?»\n**Ответ:** Глобальный мультиплексор доступен любому стороннему импортируемому пакету в приложении. Вредоносная или плохо написанная библиотека может зарегистрировать собственный обработчик (например, `/debug/pprof` или бэкдор) в `DefaultServeMux` без ведома разработчика.'}, {'num': 6, 'title': 'Преобразование функций в обработчики с помощью адаптера http.HandlerFunc', 'task': 'Используй `http.HandlerFunc` для привязки обычной функции к маршруту.', 'theory': '`http.HandlerFunc` — это тип-адаптер в стандартной библиотеке Go:\n```go\ntype HandlerFunc func(ResponseWriter, *Request)\n\nfunc (f HandlerFunc) ServeHTTP(w ResponseWriter, r *Request) {\n    f(w, r)\n}\n```\nОн позволяет обычную функцию превратить в интерфейс `http.Handler`. Метод `mux.Handle(pattern, handler)` принимает интерфейс `http.Handler`, поэтому обычную функцию туда передают через приведение типа: `mux.Handle("/path", http.HandlerFunc(myFunc))`.', 'step_by_step': '1. Объявим функцию `greet(w, r)`.\n2. Приведем ее к `http.HandlerFunc(greet)`.\n3. Зарегистрируем через `mux.Handle("/greet", http.HandlerFunc(greet))`.\n4. Проверим вызов через клиент.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc greet(w http.ResponseWriter, r *http.Request) {\n\tfmt.Fprint(w, "Привет через HandlerFunc адаптер!")\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\n\t// Приведение функции к типу http.HandlerFunc, удовлетворяющему интерфейсу http.Handler\n\tvar handler http.Handler = http.HandlerFunc(greet)\n\tmux.Handle("/greet", handler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/greet")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("[Ответ] %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Ответ] Привет через HandlerFunc адаптер!'}], 'under_the_hood': 'Вызов `mux.HandleFunc(pattern, fn)` внутри себя выполняет ровно то же действие: `mux.Handle(pattern, HandlerFunc(fn))`.', 'pitfalls': 'Не путайте тип `http.HandlerFunc` (тип-адаптер функции) и метод `mux.HandleFunc` (метод регистрации маршрута на мультиплексоре).', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен адаптер http.HandlerFunc, если есть mux.HandleFunc?»\n**Ответ:** `HandlerFunc` позволяет передавать обычные функции в middleware и любые внешние библиотеки, которые ожидают на вход строгий интерфейс `http.Handler` (например, `mux.Handle`, декораторы и цепочки middleware).'}, {'num': 7, 'title': 'Регистрация независимых маршрутов и разграничение путей в ServeMux', 'task': 'Зарегистрируйте несколько хендлеров с помощью `http.HandleFunc` для разных путей (`/home`, `/about`).', 'theory': '`http.ServeMux` сопоставляет входящие запросы по правилу наибольшего совпадения (Longest Prefix Match). Если зарегистрированы маршруты `/home` и `/about`, каждый запрос направляется строго в свой обработчик.', 'step_by_step': '1. Создадим `mux := http.NewServeMux()`.\n2. Зарегистрируем `/home` с описанием главной страницы.\n3. Зарегистрируем `/about` с информацией о сервисе.\n4. Протестируем оба маршрута.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tmux := http.NewServeMux()\n\n\tmux.HandleFunc("/home", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Домашняя страница портала")\n\t})\n\n\tmux.HandleFunc("/about", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "О компании: разрабатываем HighLoad сервисы на Go")\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tfor _, endpoint := range []string{"/home", "/about"} {\n\t\tres, _ := http.Get(ts.URL + endpoint)\n\t\tb, _ := io.ReadAll(res.Body)\n\t\tres.Body.Close()\n\t\tfmt.Printf("%-7s -> %s\\n", endpoint, string(b))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# /home   -> Домашняя страница портала\n# /about  -> О компании: разрабатываем HighLoad сервисы на Go'}], 'under_the_hood': '`ServeMux` хранит список шаблонов путей в отсортированном виде и проверяет совпадение через префиксное сканирование.', 'pitfalls': 'Слэш в конце маршрута имеет значение: `/about/` матчит все пути с префиксом `/about/...` (поддерево), тогда как `/about` требует точного совпадения.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит при переходе по URL без замыкающего слэша, если хендлер зарегистрирован со слэшем (например, /images/)?»\n**Ответ:** Стандартный `http.ServeMux` автоматически отправляет клиенту постоянный редирект `301 Moved Permanently` с URL `/images` на `/images/`.'}, {'num': 8, 'title': 'Ручной парсинг Path-параметров без сторонних библиотек', 'task': 'Напиши **handler с path-параметрами** без фреймворков: `GET /users/123/profile`. Используй `strings.TrimPrefix(r.URL.Path, "/users/")` + `strings.Split` для извлечения `id`. Верни `"user_id": 123`.', 'theory': 'До Go 1.22 в стандартном `http.ServeMux` не было встроенных шаблонов вида `{id}`. Разработчикам приходилось извлекать параметры вручную с помощью строковых манипуляций (`strings.TrimPrefix`, `strings.Split`) или регулярных выражений.', 'step_by_step': '1. Зарегистрируем маршрут с префиксом поддерева `/users/`.\n2. Проверим метод запроса `if r.Method != http.MethodGet`.\n3. Отрежем префикс и разобьем остаток пути по символу `/`.\n4. Спарсим идентификатор в `int` через `strconv.Atoi`.\n5. Вернем JSON-ответ.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strconv"\n\t"strings"\n)\n\ntype UserProfileResponse struct {\n\tUserID int    `json:"user_id"`\n\tStatus string `json:"status"`\n}\n\nfunc usersProfileHandler(w http.ResponseWriter, r *http.Request) {\n\tif r.Method != http.MethodGet {\n\t\thttp.Error(w, "Метод не поддерживается", http.StatusMethodNotAllowed)\n\t\treturn\n\t}\n\n\t// Ожидаемый путь: /users/<id>/profile\n\ttrimmed := strings.TrimPrefix(r.URL.Path, "/users/")\n\tparts := strings.Split(trimmed, "/")\n\n\tif len(parts) != 2 || parts[1] != "profile" {\n\t\thttp.NotFound(w, r)\n\t\treturn\n\t}\n\n\tuserID, err := strconv.Atoi(parts[0])\n\tif err != nil || userID <= 0 {\n\t\thttp.Error(w, "Некорректный ID пользователя", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tw.Header().Set("Content-Type", "application/json")\n\t_ = json.NewEncoder(w).Encode(UserProfileResponse{\n\t\tUserID: userID,\n\t\tStatus: "active",\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/users/", usersProfileHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/users/123/profile")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("[Status] %d\\n", resp.StatusCode)\n\tfmt.Printf("[JSON]   %s", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status] 200\n# [JSON]   {"user_id":123,"status":"active"}'}], 'under_the_hood': 'Маршрутизатор сопоставляет префикс `/users/`, а всю остальную валидацию структуры пути выполняет сам хендлер.', 'pitfalls': 'При ручном парсинге легко пропустить краевые случаи: двойные слэши `//`, отсутствие суффикса или отрицательные числа.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему исторически многие Go-проекты использовали chi или gorilla/mux вместо стандартного ServeMux?»\n**Ответ:** Стандартный ServeMux до Go 1.22 не умел валидировать HTTP-методы (GET/POST) и извлекать переменные пути `{id}` из коробки, что заставляло писать громоздкий бойлерплейт. Сторонние роутеры решали эту проблему на основе Radix Tree.'}, {'num': 9, 'title': 'Изоляция контекста роутинга с помощью явного http.NewServeMux', 'task': 'Используйте `http.ServeMux` (созданный явно через `http.NewServeMux()`, а не глобальный `http.DefaultServeMux`) для изоляции роутинга.', 'theory': 'Использование локальных экземпляров `ServeMux` — ключевой архитектурный паттерн безопасного кода в Go. Каждый микросервис или юнит-тест обязан иметь свой собственный независимый экземпляр роутера, исключая побочные эффекты через глобальное состояние.', 'step_by_step': '1. Создадим два независимых мультиплексора: `adminMux` и `publicMux`.\n2. Зарегистрируем на них разные маршруты.\n3. Убедимся, что маршруты одного мультиплексора недоступны на другом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\t// Публичный роутер\n\tpublicMux := http.NewServeMux()\n\tpublicMux.HandleFunc("/catalog", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Каталог товаров")\n\t})\n\n\t// Административный роутер\n\tadminMux := http.NewServeMux()\n\tadminMux.HandleFunc("/metrics", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Метрики сервера")\n\t})\n\n\ttsPublic := httptest.NewServer(publicMux)\n\tdefer tsPublic.Close()\n\n\ttsAdmin := httptest.NewServer(adminMux)\n\tdefer tsAdmin.Close()\n\n\tres1, _ := http.Get(tsPublic.URL + "/catalog")\n\tres1.Body.Close()\n\tfmt.Println("PublicServer /catalog:", res1.StatusCode)\n\n\tres2, _ := http.Get(tsPublic.URL + "/metrics")\n\tres2.Body.Close()\n\tfmt.Println("PublicServer /metrics (должен быть 404):", res2.StatusCode)\n\n\tres3, _ := http.Get(tsAdmin.URL + "/metrics")\n\tres3.Body.Close()\n\tfmt.Println("AdminServer /metrics:", res3.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# PublicServer /catalog: 200\n# PublicServer /metrics (должен быть 404): 404\n# AdminServer /metrics: 200'}], 'under_the_hood': '`http.NewServeMux()` выделяет новую структуру `ServeMux` с собственной приватной мапой шаблонов `tree`, полностью изолированной в памяти.', 'pitfalls': 'Вызов `http.HandleFunc(...)` вместо `mux.HandleFunc(...)` неявно пишет в `DefaultServeMux`, нарушая изоляцию.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в одном бинарнике Go запустить публичный API на порту 8080 и админку/метрики на порту 9090?»\n**Ответ:** Создать два разных `ServeMux`: `apiMux` и `adminMux`, привязать их к двум структурам `http.Server{Addr: ":8080", Handler: apiMux}` и `http.Server{Addr: ":9090", Handler: adminMux}`, и запустить каждый сервер в своей отдельной горутине.'}, {'num': 10, 'title': 'Извлечение и валидация Query-параметров из URL запроса', 'task': 'Извлеки query-параметры из входящего запроса: `r.URL.Query().Get("name")`. Выведи приветствие с этим именем.', 'theory': 'Строка запроса (Query String) передается после знака `?` в формате `k1=v1&k2=v2`. Метод `r.URL.Query()` возвращает тип `url.Values` (`map[string][]string`). Метод `Get(key)` возвращает первое значение параметра или пустую строку `""`, если параметр не был передан.', 'step_by_step': '1. Создадим обработчик `/greet`.\n2. Извлечем параметр `name` через `r.URL.Query().Get("name")`.\n3. Если имя не задано, используем дефолтное значение `"Гость"`.\n4. Протестируем вызовы с параметром и без него.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc greetHandler(w http.ResponseWriter, r *http.Request) {\n\tname := r.URL.Query().Get("name")\n\tif name == "" {\n\t\tname = "Гость"\n\t}\n\tfmt.Fprintf(w, "Добро пожаловать, %s!", name)\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/greet", greetHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// Запрос с параметром\n\tr1, _ := http.Get(ts.URL + "/greet?name=Алексей")\n\tb1, _ := io.ReadAll(r1.Body)\n\tr1.Body.Close()\n\tfmt.Println(string(b1))\n\n\t// Запрос без параметра\n\tr2, _ := http.Get(ts.URL + "/greet")\n\tb2, _ := io.ReadAll(r2.Body)\n\tr2.Body.Close()\n\tfmt.Println(string(b2))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Добро пожаловать, Алексей!\n# Добро пожаловать, Гость!'}], 'under_the_hood': '`r.URL.Query()` каждый раз парсит сырую строку `r.URL.RawQuery`. Для оптимизации при многократном чтении параметров в рамках одного запроса результат вызова сохраняют в локальную переменную.', 'pitfalls': 'Метод `Get()` возвращает только первое значение. Если параметр передан несколько раз (`?tag=go&tag=web`), для получения всех значений нужно обращаться к мапе напрямую: `r.URL.Query()["tag"]`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между r.URL.Query().Get("key") и r.FormValue("key")?»\n**Ответ:** `r.URL.Query()` читает параметры только из строки URL (GET). `r.FormValue("key")` проверяет и строку URL, и тело запроса `application/x-www-form-urlencoded` (POST/PUT), автоматически вызывая `r.ParseMultipartForm` при необходимости.'}, {'num': 11, 'title': 'Клиентский HTTP-запрос к API с проверкой статуса', 'task': 'Реализуйте HTTP-клиент, делающий GET-запрос к публичному API (например, `https://api.github.com`) и выводящий статус ответа.', 'theory': 'Для взаимодействия между микросервисами используется `http.Client`. Надежный клиент всегда настраивает таймаут `Timeout`, проверяет ошибки сети `err != nil` и обязательно закрывает `resp.Body.Close()`.', 'step_by_step': '1. Создадим мок-сервер для имитации внешнего API.\n2. Сконфигурируем `http.Client` с таймаутом.\n3. Выполним GET-запрос и выведем статус ответа.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc main() {\n\tmockAPI := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("X-RateLimit-Remaining", "59")\n\t\tw.WriteHeader(http.StatusOK)\n\t\t_, _ = w.Write([]byte(`{"message": "API Active"}`))\n\t}))\n\tdefer mockAPI.Close()\n\n\tclient := &http.Client{\n\t\tTimeout: 5 * time.Second,\n\t}\n\n\tresp, err := client.Get(mockAPI.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tfmt.Printf("[Клиент] Ответ получен от: %s\\n", mockAPI.URL)\n\tfmt.Printf("[Клиент] Статус: %d (%s)\\n", resp.StatusCode, resp.Status)\n\tfmt.Printf("[Клиент] Лимит запросов оставшийся: %s\\n", resp.Header.Get("X-RateLimit-Remaining"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Клиент] Ответ получен от: http://127.0.0.1:...\n# [Клиент] Статус: 200 (200 OK)\n# [Клиент] Лимит запросов оставшийся: 59'}], 'under_the_hood': '`client.Get` оборачивает вызов `client.Do(req)`, инициализируя транспорт `http.Transport` с пулом Keep-Alive соединений.', 'pitfalls': 'Использование `http.Get` без таймаута в микросервисах может вызвать зависание горутин при сетевом сбое на стороне поставщика API.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем клиенту вычитывать resp.Body, даже если само тело ответа не нужно?»\n**Ответ:** Если не вычитать тело до конца (`io.Copy(io.Discard, resp.Body)`), TCP-соединение не сможет вернуться в пул Keep-Alive и будет разорвано, что заставит следующий запрос открывать новый сокет и делать TLS-хэндшейк заново.'}, {'num': 12, 'title': 'Полноценный in-memory CRUD REST API для сущности User с RWMutex', 'task': 'Напиши **REST API** с полным CRUD (in-memory `map[int]User` + `sync.RWMutex`):\n- `GET /users` — список\n- `GET /users/{id}` — один пользователь\n- `POST /users` — создать\n- `PUT /users/{id}` — обновить\n- `DELETE /users/{id}` — удалить', 'theory': 'CRUD (Create, Read, Update, Delete) — стандарт архитектуры REST:\n- `GET` — идемпотентное получение ресурса (200 OK, 404 Not Found).\n- `POST` — создание нового ресурса (201 Created с заголовком Location).\n- `PUT` — полная замена ресурса по ID (200 OK).\n- `DELETE` — удаление ресурса (204 No Content или 200 OK).\nДля потокобезопасности хранилища в памяти используется `sync.RWMutex`: параллельные чтения `RLock` и эксклюзивная запись `Lock`.', 'step_by_step': '1. Опишем структуру `User { ID, Name, Email }`.\n2. Создадим хранилище `UserStore` с `sync.RWMutex` и мапой `map[int]User`.\n3. Зарегистрируем маршруты с новым синтаксисом Go 1.22+.\n4. Протестируем весь жизненный цикл пользователя: Create -> List -> Get -> Update -> Delete.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strconv"\n\t"sync"\n)\n\ntype User struct {\n\tID    int    `json:"id"`\n\tName  string `json:"name"`\n\tEmail string `json:"email"`\n}\n\ntype UserStore struct {\n\tmu     sync.RWMutex\n\tusers  map[int]User\n\tnextID int\n}\n\nfunc NewUserStore() *UserStore {\n\treturn &UserStore{users: make(map[int]User), nextID: 1}\n}\n\nfunc (s *UserStore) Create(u User) User {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\tu.ID = s.nextID\n\ts.nextID++\n\ts.users[u.ID] = u\n\treturn u\n}\n\nfunc (s *UserStore) GetAll() []User {\n\ts.mu.RLock()\n\tdefer s.mu.RUnlock()\n\tlist := make([]User, 0, len(s.users))\n\tfor _, u := range s.users {\n\t\tlist = append(list, u)\n\t}\n\treturn list\n}\n\nfunc (s *UserStore) Get(id int) (User, bool) {\n\ts.mu.RLock()\n\tdefer s.mu.RUnlock()\n\tu, ok := s.users[id]\n\treturn u, ok\n}\n\nfunc (s *UserStore) Update(id int, u User) bool {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\tif _, exists := s.users[id]; !exists {\n\t\treturn false\n\t}\n\tu.ID = id\n\ts.users[id] = u\n\treturn true\n}\n\nfunc (s *UserStore) Delete(id int) bool {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\tif _, exists := s.users[id]; !exists {\n\t\treturn false\n\t}\n\tdelete(s.users, id)\n\treturn true\n}\n\nfunc main() {\n\tstore := NewUserStore()\n\tmux := http.NewServeMux()\n\n\tmux.HandleFunc("GET /users", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\t_ = json.NewEncoder(w).Encode(store.GetAll())\n\t})\n\n\tmux.HandleFunc("POST /users", func(w http.ResponseWriter, r *http.Request) {\n\t\tvar u User\n\t\tif err := json.NewDecoder(r.Body).Decode(&u); err != nil {\n\t\t\thttp.Error(w, err.Error(), http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\t\tcreated := store.Create(u)\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tw.WriteHeader(http.StatusCreated)\n\t\t_ = json.NewEncoder(w).Encode(created)\n\t})\n\n\tmux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tid, err := strconv.Atoi(r.PathValue("id"))\n\t\tif err != nil {\n\t\t\thttp.Error(w, "invalid id", http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\t\tu, ok := store.Get(id)\n\t\tif !ok {\n\t\t\thttp.NotFound(w, r)\n\t\t\treturn\n\t\t}\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\t_ = json.NewEncoder(w).Encode(u)\n\t})\n\n\tmux.HandleFunc("PUT /users/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tid, err := strconv.Atoi(r.PathValue("id"))\n\t\tif err != nil {\n\t\t\thttp.Error(w, "invalid id", http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\t\tvar u User\n\t\tif err := json.NewDecoder(r.Body).Decode(&u); err != nil {\n\t\t\thttp.Error(w, err.Error(), http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\t\tif !store.Update(id, u) {\n\t\t\thttp.NotFound(w, r)\n\t\t\treturn\n\t\t}\n\t\tw.WriteHeader(http.StatusOK)\n\t\tfmt.Fprint(w, `{"status":"updated"}`)\n\t})\n\n\tmux.HandleFunc("DELETE /users/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tid, err := strconv.Atoi(r.PathValue("id"))\n\t\tif err != nil {\n\t\t\thttp.Error(w, "invalid id", http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\t\tif !store.Delete(id) {\n\t\t\thttp.NotFound(w, r)\n\t\t\treturn\n\t\t}\n\t\tw.WriteHeader(http.StatusNoContent)\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// 1. POST /users\n\tres, _ := http.Post(ts.URL+"/users", "application/json", bytes.NewBufferString(`{"name":"Иван","email":"ivan@ya.ru"}`))\n\tvar created User\n\t_ = json.NewDecoder(res.Body).Decode(&created)\n\tres.Body.Close()\n\tfmt.Printf("[1. POST] ID: %d, Name: %s\\n", created.ID, created.Name)\n\n\t// 2. GET /users/1\n\tres, _ = http.Get(ts.URL + "/users/1")\n\tb, _ := io.ReadAll(res.Body)\n\tres.Body.Close()\n\tfmt.Printf("[2. GET]  %s\\n", string(b))\n\n\t// 3. DELETE /users/1\n\treq, _ := http.NewRequest(http.MethodDelete, ts.URL+"/users/1", nil)\n\tdelRes, _ := http.DefaultClient.Do(req)\n\tdelRes.Body.Close()\n\tfmt.Printf("[3. DEL]  Status: %d\\n", delRes.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [1. POST] ID: 1, Name: Иван\n# [2. GET]  {"id":1,"name":"Иван","email":"ivan@ya.ru"}\n# [3. DEL]  Status: 204'}], 'under_the_hood': 'В Go 1.22 роутер `ServeMux` компилирует методы (`GET`, `POST`, `DELETE`) и переменные `{id}` в дерево префиксов, избавляя от необходимости кастомных свитчей по `r.Method`.', 'pitfalls': 'Не забывайте, что чтение из мапы в Go при одновременной записи без мьютекса приводит к `fatal error: concurrent map read and map write`, роняющей весь сервер без возможности восстановления через `recover()`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие семантики PUT от PATCH в REST API?»\n**Ответ:** `PUT` означает полную замену сущности (клиент обязан прислать все поля; неуказанные поля сбрасываются в значения по умолчанию). `PATCH` выполняет частичное обновление только тех полей, которые были явно переданы в теле запроса.'}, {'num': 13, 'title': 'Комбинирование Path-параметров и Query-параметров пагинации', 'task': 'Извлеките значение переменной пути (`id` через `r.PathValue("id")`) и query-параметры (`?page=2&sort=desc` через `r.URL.Query()`).', 'theory': 'В реальных API параметры идентификации ресурса помещают в путь (`/categories/{id}/items`), а параметры представления и фильтрации — в query-строку (`?page=2&sort=desc&limit=20`).', 'step_by_step': '1. Зарегистрируем маршрут `GET /categories/{id}/products`.\n2. Извлечем категорию через `r.PathValue("id")`.\n3. Извлечем query-параметры `page` и `sort` через `r.URL.Query()`.\n4. Сформируем и вернем комплексный JSON-ответ.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype QueryInfo struct {\n\tCategoryID string `json:"category_id"`\n\tPage       string `json:"page"`\n\tSort       string `json:"sort"`\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\n\tmux.HandleFunc("GET /categories/{id}/products", func(w http.ResponseWriter, r *http.Request) {\n\t\tcategoryID := r.PathValue("id")\n\t\tq := r.URL.Query()\n\t\tpage := q.Get("page")\n\t\tif page == "" {\n\t\t\tpage = "1"\n\t\t}\n\t\tsortOrder := q.Get("sort")\n\t\tif sortOrder == "" {\n\t\t\tsortOrder = "asc"\n\t\t}\n\n\t\tinfo := QueryInfo{\n\t\t\tCategoryID: categoryID,\n\t\t\tPage:       page,\n\t\t\tSort:       sortOrder,\n\t\t}\n\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\t_ = json.NewEncoder(w).Encode(info)\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/categories/electronics/products?page=3&sort=desc")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Println(string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"category_id":"electronics","page":"3","sort":"desc"}'}], 'under_the_hood': '`r.PathValue("key")` считывает значение из внутреннего контекста `http.Request`, которое туда поместил роутер при сопоставлении шаблона пути.', 'pitfalls': '`r.PathValue` возвращает строку. Если ожидается число, обязательно выполняйте конвертацию через `strconv.Atoi` с обработкой ошибок.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда передавать параметры через Path, а когда через Query?»\n**Ответ:** Через Path передают уникальные идентификаторы иерархии ресурсов (`/orders/123/items/4`). Через Query передают необязательные параметры: фильтры, сортировку, пагинацию, проекцию полей (`?status=paid&limit=10`).'}, {'num': 14, 'title': 'Продвинутый роутинг в Go 1.22+: сопоставление метода и переменной пути', 'task': '**[Сложный роутинг (Go 1.22+)]**: Используй новый синтаксис роутинга: `mux.HandleFunc("GET /users/{id}", ...)`. Извлеки `id` из `r.PathValue("id")`.', 'theory': 'С выходом Go 1.22 стандартный `http.ServeMux` получил революционное обновление:\n1. Задание HTTP-метода в начале шаблона: `"GET /path"`, `"POST /path"`.\n2. Поддержка параметров в фигурных скобках: `"/users/{id}"`.\n3. Поддержка остаточных путей (wildcard): `"/files/{path...}"`.\n4. Извлечение через `r.PathValue(name)`.', 'step_by_step': '1. Зарегистрируем `GET /users/{id}`.\n2. Зарегистрируем `POST /users/{id}/activate`.\n3. Проверим автоматический возврат `405 Method Not Allowed`, если запросить POST на GET-маршрут.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\tmux := http.NewServeMux()\n\n\tmux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tid := r.PathValue("id")\n\t\tfmt.Fprintf(w, "Профиль пользователя #%s", id)\n\t})\n\n\tmux.HandleFunc("POST /users/{id}/activate", func(w http.ResponseWriter, r *http.Request) {\n\t\tid := r.PathValue("id")\n\t\tw.WriteHeader(http.StatusOK)\n\t\tfmt.Fprintf(w, "Пользователь #%s активирован", id)\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// 1. Успешный GET\n\tres1, _ := http.Get(ts.URL + "/users/42")\n\tb1, _ := io.ReadAll(res1.Body)\n\tres1.Body.Close()\n\tfmt.Printf("[GET /users/42] %d: %s\\n", res1.StatusCode, string(b1))\n\n\t// 2. Неверный метод POST на GET-маршрут (автоматический 405 Method Not Allowed!)\n\tres2, _ := http.Post(ts.URL+"/users/42", "text/plain", nil)\n\tres2.Body.Close()\n\tfmt.Printf("[POST /users/42] Ожидается 405 -> Получен: %d %s\\n", res2.StatusCode, res2.Status)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [GET /users/42] 200: Профиль пользователя #42\n# [POST /users/42] Ожидается 405 -> Получен: 405 405 Method Not Allowed'}], 'under_the_hood': 'Если маршрут совпал по пути, но метод не подошел, `ServeMux` автоматически формирует ответ `405 Method Not Allowed` с заголовком `Allow`, перечисляющим разрешенные методы.', 'pitfalls': 'Синтаксис `"GET /users/{id}"` требует ровно одного пробела между методом и путем.', 'bigtech_interview': '**Вопрос с собеседования:** «Что означает шаблон вида /files/{filepath...} в Go 1.22+?»\n**Ответ:** Это подстановочный знак (wildcard), который матчит весь остаток пути включая наклонные черты `/`. Значение извлекается через `r.PathValue("filepath")` (идеально для файловых серверов и проксирования).'}, {'num': 15, 'title': 'JSON API хендлер с валидацией входных данных и статусом 201 Created', 'task': 'Напиши **JSON API handler**: `POST /api/users`. Прочитай тело `r.Body` (`json.NewDecoder(r.Body).Decode(&user)`), валидируй (имя не пустое, возраст > 0), верни `201 Created` с созданным JSON. Не забудь `defer r.Body.Close()`. Без `r.Body.Close()` утекают сокеты!', 'theory': 'При приеме входных JSON данных обработчик обязан:\n1. Ограничить размер тела запроса (например, через `http.MaxBytesReader`), защищая от OOM.\n2. Выполнить парсинг через `json.NewDecoder`.\n3. Валидировать бизнес-правила (непустые строки, корректные диапазоны).\n4. Вернуть `400 Bad Request` при ошибке или `201 Created` с JSON нового объекта.', 'step_by_step': '1. Опишем входную структуру `NewUserRequest { Name, Age }`.\n2. Настроим проверку `Name != ""` и `Age > 0`.\n3. Вернем `201 Created` и сериализованный ответ.\n4. Протестируем валидный и невалидный запросы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strings"\n)\n\ntype CreateUserDTO struct {\n\tName string `json:"name"`\n\tAge  int    `json:"age"`\n}\n\ntype UserResponse struct {\n\tID   int    `json:"id"`\n\tName string `json:"name"`\n\tAge  int    `json:"age"`\n}\n\nfunc createUserHandler(w http.ResponseWriter, r *http.Request) {\n\tdefer r.Body.Close()\n\n\t// Ограничиваем тело 1 мегабайтом для защиты сервера\n\tr.Body = http.MaxBytesReader(w, r.Body, 1048576)\n\n\tvar dto CreateUserDTO\n\tif err := json.NewDecoder(r.Body).Decode(&dto); err != nil {\n\t\thttp.Error(w, "Невалидный JSON формат", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tdto.Name = strings.TrimSpace(dto.Name)\n\tif dto.Name == "" {\n\t\thttp.Error(w, "Имя не может быть пустым", http.StatusBadRequest)\n\t\treturn\n\t}\n\tif dto.Age <= 0 || dto.Age > 150 {\n\t\thttp.Error(w, "Некорректный возраст (должен быть 1-150)", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tuser := UserResponse{\n\t\tID:   101,\n\t\tName: dto.Name,\n\t\tAge:  dto.Age,\n\t}\n\n\tw.Header().Set("Content-Type", "application/json")\n\tw.WriteHeader(http.StatusCreated)\n\t_ = json.NewEncoder(w).Encode(user)\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("POST /api/users", createUserHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// 1. Успешный запрос\n\tres1, _ := http.Post(ts.URL+"/api/users", "application/json", bytes.NewBufferString(`{"name":"Ольга","age":28}`))\n\tb1, _ := io.ReadAll(res1.Body)\n\tres1.Body.Close()\n\tfmt.Printf("[Valid POST] Status: %d, Body: %s", res1.StatusCode, string(b1))\n\n\t// 2. Невалидный возраст\n\tres2, _ := http.Post(ts.URL+"/api/users", "application/json", bytes.NewBufferString(`{"name":"Ольга","age":-5}`))\n\tb2, _ := io.ReadAll(res2.Body)\n\tres2.Body.Close()\n\tfmt.Printf("[Invalid POST] Status: %d, Err: %s", res2.StatusCode, string(b2))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Valid POST] Status: 201, Body: {"id":101,"name":"Ольга","age":28}\n# [Invalid POST] Status: 400, Err: Некорректный возраст (должен быть 1-150)'}], 'under_the_hood': '`http.MaxBytesReader` оборачивает входящий поток и возвращает ошибку, если прочитано больше байт, чем задано лимитом, предотвращая переполнение памяти.', 'pitfalls': 'Если клиент отправляет пустой запрос или сломанный JSON, `Decode` вернет `io.EOF` или синтаксическую ошибку `*json.SyntaxError`, которую нужно перехватывать и возвращать 400.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен http.MaxBytesReader при обработке POST JSON запросов?»\n**Ответ:** Злоумышленник может отправить HTTP POST запрос с бесконечным телом (Denial of Service). Без `MaxBytesReader` сервер попытается вычитать всё тело в память или диск, что приведет к исчерпанию RAM (OOM Crash). `MaxBytesReader` принудительно обрывает чтение.'}, {'num': 16, 'title': 'Симметричная обработка: десериализация и подтверждение эхо-ответом', 'task': 'Отправьте POST-запрос с JSON-телом на свой сервер. Сервер должен распарсить тело в структуру и вернуть её обратно с подтверждением.', 'theory': 'Паттерн Echo-Validation: сервер принимает запрос, валидирует схему и возвращает обогащенную структуру с подтверждением приема (Acknowledgement).', 'step_by_step': '1. Создадим структуру `OrderRequest { OrderID, Amount, Currency }`.\n2. Создадим ответ `OrderAck { OrderRequest, Processed: true, Timestamp }`.\n3. Отправим POST-запрос из клиента и распарсим подтверждение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\ntype OrderRequest struct {\n\tOrderID  string  `json:"order_id"`\n\tAmount   float64 `json:"amount"`\n\tCurrency string  `json:"currency"`\n}\n\ntype OrderAck struct {\n\tOrder     OrderRequest `json:"order"`\n\tProcessed bool         `json:"processed"`\n\tTimestamp string       `json:"timestamp"`\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tvar req OrderRequest\n\t\tif err := json.NewDecoder(r.Body).Decode(&req); err != nil {\n\t\t\thttp.Error(w, err.Error(), http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\t\tdefer r.Body.Close()\n\n\t\tack := OrderAck{\n\t\t\tOrder:     req,\n\t\t\tProcessed: true,\n\t\t\tTimestamp: time.Now().UTC().Format(time.RFC3339),\n\t\t}\n\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\t_ = json.NewEncoder(w).Encode(ack)\n\t}))\n\tdefer ts.Close()\n\n\torder := OrderRequest{OrderID: "ORD-9912", Amount: 2450.50, Currency: "RUB"}\n\tdata, _ := json.Marshal(order)\n\n\tres, err := http.Post(ts.URL, "application/json", bytes.NewReader(data))\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer res.Body.Close()\n\n\tvar ack OrderAck\n\t_ = json.NewDecoder(res.Body).Decode(&ack)\n\n\tfmt.Printf("[Сервер подтвердил заказ] ID: %s | Сумма: %.2f %s | Время: %s\\n",\n\t\tack.Order.OrderID, ack.Order.Amount, ack.Order.Currency, ack.Timestamp)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Сервер подтвердил заказ] ID: ORD-9912 | Сумма: 2450.50 RUB | Время: 2026-09-03T09:48:00Z'}], 'under_the_hood': '`bytes.NewReader(data)` реализует `io.Reader`, позволяя отправлять байты в тело запроса без дополнительных копирований.', 'pitfalls': 'Если не установить `Content-Type: application/json` на клиенте, серверы на других языках или со строгими middleware отклонят запрос с кодом `415 Unsupported Media Type`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как обработать ситуацию, когда клиент шлет заголовок Content-Encoding: gzip?»\n**Ответ:** Необходимо проверить заголовок `r.Header.Get("Content-Encoding") == "gzip"`, и если он присутствует, обернуть `r.Body` в `gzip.NewReader(r.Body)` перед передачей в `json.NewDecoder`.'}, {'num': 17, 'title': 'Строгая десериализация JSON с DisallowUnknownFields для защиты API', 'task': 'Напишите хендлер, который принимает JSON в теле запроса, десериализует его в структуру (используйте `json.Decoder` и `DisallowUnknownFields`) и возвращает JSON-ответ.', 'theory': 'По умолчанию `encoding/json` в Go молча игнорирует неизвестные поля, пришедшие в JSON. Это опасно: опечатка в поле (например, `user_nmae` вместо `username`) оставит поле пустым без сообщения об ошибке. Метод `decoder.DisallowUnknownFields()` заставляет декодер возвращать ошибку при обнаружении любого непредусмотренного схемой поля.', 'step_by_step': '1. Создадим декодер `dec := json.NewDecoder(r.Body)`.\n2. Включим строгий режим `dec.DisallowUnknownFields()`.\n3. Отправим запрос с лишним полем `admin: true`.\n4. Убедимся, что сервер отклонил такой запрос.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype StrictUser struct {\n\tUsername string `json:"username"`\n\tEmail    string `json:"email"`\n}\n\nfunc strictHandler(w http.ResponseWriter, r *http.Request) {\n\tdefer r.Body.Close()\n\n\tdec := json.NewDecoder(r.Body)\n\tdec.DisallowUnknownFields() // Запрещаем неизвестные поля!\n\n\tvar user StrictUser\n\tif err := dec.Decode(&user); err != nil {\n\t\thttp.Error(w, fmt.Sprintf("Ошибка схемы: %v", err), http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tw.WriteHeader(http.StatusOK)\n\tfmt.Fprintf(w, "Пользователь %s успешно принят", user.Username)\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(strictHandler))\n\tdefer ts.Close()\n\n\t// Попытка отправить несанкционированное поле "is_admin"\n\tbadJSON := `{"username": "hacker", "email": "h@sec.ru", "is_admin": true}`\n\tres, _ := http.Post(ts.URL, "application/json", bytes.NewBufferString(badJSON))\n\tbody, _ := io.ReadAll(res.Body)\n\tres.Body.Close()\n\n\tfmt.Printf("[Status] %d\\n", res.StatusCode)\n\tfmt.Printf("[Error]  %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status] 400\n# [Error]  Ошибка схемы: json: unknown field "is_admin" '}], 'under_the_hood': '`DisallowUnknownFields` сравнивает ключи JSON с именами экспортируемых полей и их тегами `json:"..."`. Если ключ не найден, парсер прерывается с ошибкой.', 'pitfalls': "В микросервисной архитектуре `DisallowUnknownFields` может усложнить эволюцию API, если старые сервисы перестанут принимать ответы с новыми добавленными полями (нарушение Postel's Law).", 'bigtech_interview': '**Вопрос с собеседования:** «Как DisallowUnknownFields защищает от уязвимостей Mass Assignment?»\n**Ответ:** Без этой опции злоумышленник может передать скрытые поля вроде `role: "admin"` или `balance: 99999`. Если структура используется повторно или мапится в БД без фильтрации, это может привести к несанкционированному повышению привилегий.'}, {'num': 18, 'title': 'Композиция цепочки Middleware: паттерн луковицы (Onion Architecture)', 'task': 'Напиши **middleware chain**: `LoggingMiddleware → AuthMiddleware → RateLimitMiddleware → Handler`. Покажи композицию: `chain := Logging(RateLimit(Auth(handler)))`.', 'theory': 'Middleware в Go оборачивает `http.Handler`, образуя цепочку декораторов:\nЗапрос проходит снаружи внутрь:\n`Logging -> RateLimit -> Auth -> Финальный хендлер`\nЗатем ответ возвращается изнутри наружу:\n`Финальный хендлер -> Auth -> RateLimit -> Logging`\nТакая композиция называется «архитектурой луковицы» (Onion Architecture).', 'step_by_step': '1. Создадим три middleware: `Logging`, `RateLimit`, `Auth`.\n2. Каждое middleware логирует вход и выход.\n3. Соберем цепочку: `chain := Logging(RateLimit(Auth(finalHandler)))`.\n4. Выполним тестовый запрос и проследим порядок вызовов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype Middleware func(http.Handler) http.Handler\n\nfunc LoggingMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println(" -> [1. Logging] Вход")\n\t\tnext.ServeHTTP(w, r)\n\t\tfmt.Println(" <- [1. Logging] Выход")\n\t})\n}\n\nfunc RateLimitMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println("  -> [2. RateLimit] Проверка лимитов: OK")\n\t\tnext.ServeHTTP(w, r)\n\t\tfmt.Println("  <- [2. RateLimit] Завершение")\n\t})\n}\n\nfunc AuthMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println("   -> [3. Auth] Проверка авторизации: OK")\n\t\tnext.ServeHTTP(w, r)\n\t\tfmt.Println("   <- [3. Auth] Завершение")\n\t})\n}\n\nfunc finalHandler(w http.ResponseWriter, r *http.Request) {\n\tfmt.Println("    [★ Обработчик] Выполнение бизнес-логики...")\n\tfmt.Fprint(w, "Success!")\n}\n\nfunc main() {\n\t// Композиция цепочки Middleware\n\tchain := LoggingMiddleware(RateLimitMiddleware(AuthMiddleware(http.HandlerFunc(finalHandler))))\n\n\tts := httptest.NewServer(chain)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tresp.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> [1. Logging] Вход\n#   -> [2. RateLimit] Проверка лимитов: OK\n#    -> [3. Auth] Проверка авторизации: OK\n#     [★ Обработчик] Выполнение бизнес-логики...\n#    <- [3. Auth] Завершение\n#   <- [2. RateLimit] Завершение\n#  <- [1. Logging] Выход'}], 'under_the_hood': 'Каждое замыкание сохраняет ссылку на `next`. При вызове цепочка разворачивается через стек вызовов горутины.', 'pitfalls': 'Чем глубже цепочка вложенных функций, тем больше стек. Для удобного сбора цепочек без «лесенки скобок» используют функции-хелперы вроде `alice.New()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если в AuthMiddleware не вызвать next.ServeHTTP(w, r)?»\n**Ответ:** Запрос будет прерван (Short-circuit). Ни последующие middleware, ни целевой обработчик не выполнятся, а управление вернется наружу по цепочке завершающих секций вышестоящих middleware.'}, {'num': 19, 'title': 'Аутентификация по Bearer-токену с пробросом User ID через context.WithValue', 'task': 'Напиши **Auth middleware**: проверяй заголовок `Authorization: Bearer <token>`. Если токен неверен — верни `401 Unauthorized`. Если верен — добавь `user_id` в `context.Context` через `context.WithValue` и передай дальше.', 'theory': 'Передача метаданных аутентификации в обработчик:\n1. Middleware извлекает заголовок `Authorization`.\n2. Валидирует токен (например, JWT или Bearer).\n3. Создает новый контекст: `ctx := context.WithValue(r.Context(), userKey, userID)`.\n4. Передает в следующий обработчик копию запроса с новым контекстом: `r.WithContext(ctx)`.', 'step_by_step': '1. Создадим приватный тип ключа контекста `type contextKey string`.\n2. Напишем `BearerAuthMiddleware`.\n3. В обработчике извлечем `user_id` из `r.Context()`.\n4. Проверим запросы с валидным и невалидным токенами.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strings"\n)\n\ntype ctxKey string\n\nconst UserIDKey ctxKey = "user_id"\n\nfunc BearerAuthMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tauthHeader := r.Header.Get("Authorization")\n\t\tif !strings.HasPrefix(authHeader, "Bearer ") {\n\t\t\thttp.Error(w, "Требуется Bearer токен", http.StatusUnauthorized)\n\t\t\treturn\n\t\t}\n\n\t\ttoken := strings.TrimPrefix(authHeader, "Bearer ")\n\t\t// Симуляция проверки токена\n\t\tif token != "secret-jwt-token-42" {\n\t\t\thttp.Error(w, "Невалидный токен", http.StatusUnauthorized)\n\t\t\treturn\n\t\t}\n\n\t\t// Успех: обогащаем контекст ID пользователя\n\t\tctx := context.WithValue(r.Context(), UserIDKey, "usr_998811")\n\t\tnext.ServeHTTP(w, r.WithContext(ctx))\n\t})\n}\n\nfunc profileHandler(w http.ResponseWriter, r *http.Request) {\n\tuserID, ok := r.Context().Value(UserIDKey).(string)\n\tif !ok {\n\t\thttp.Error(w, "Пользователь не найден в контексте", http.StatusInternalServerError)\n\t\treturn\n\t}\n\tfmt.Fprintf(w, "Профиль пользователя: %s", userID)\n}\n\nfunc main() {\n\thandler := BearerAuthMiddleware(http.HandlerFunc(profileHandler))\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\t// 1. Запрос без заголовка\n\tr1, _ := http.Get(ts.URL)\n\tfmt.Printf("[Без токена]  Status: %d\\n", r1.StatusCode)\n\tr1.Body.Close()\n\n\t// 2. Запрос с верным токеном\n\treq, _ := http.NewRequest(http.MethodGet, ts.URL, nil)\n\treq.Header.Set("Authorization", "Bearer secret-jwt-token-42")\n\tr2, _ := http.DefaultClient.Do(req)\n\tb2, _ := io.ReadAll(r2.Body)\n\tr2.Body.Close()\n\tfmt.Printf("[С токеном]   Status: %d, Ответ: %s\\n", r2.StatusCode, string(b2))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Без токена]  Status: 401\n# [С токеном]   Status: 200, Ответ: Профиль пользователя: usr_998811'}], 'under_the_hood': '`r.WithContext(ctx)` создает неглубокую копию структуры `http.Request`, заменяя только указатель на `ctx`. Исходный запрос не мутирует, гарантируя потокобезопасность.', 'pitfalls': 'Никогда не используйте базовые типы вроде `string("user_id")` в качестве ключа контекста! Всегда объявляйте неэкспортируемый тип `type ctxKey struct{}` во избежание коллизий ключей между разными пакетами.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в context.WithValue рекомендуется использовать собственный тип ключа, а не обычную строку?»\n**Ответ:** Разные сторонние пакеты и middleware могут использовать строку `"user"` или `"id"` для своих нужд. Использование обычных строк приведет к коллизиям и перезаписи значений. Приватный тип `type contextKey int` гарантирует уникальность ключа на уровне всей кодовой базы.'}, {'num': 20, 'title': 'Механика WriteHeader: почему установка статуса должна быть строго до Write', 'task': 'Правильно устанавливайте HTTP статус-коды с помощью `http.Error` или `w.WriteHeader()`. Поймите, почему `WriteHeader` нужно вызывать **строго до** первой записи в `w`.', 'theory': 'Протокол HTTP требует, чтобы статусная строка и заголовки ответа (`HTTP/1.1 201 Created\\r\\n...`) передавались в сокет **до** начала передачи тела ответа. В Go при первом вызове `w.Write()` рантайн проверяет, был ли вызван `WriteHeader`. Если нет, он автоматически отправляет клиенту статус `200 OK`. После этого изменить статус-код технически невозможно.', 'step_by_step': '1. Покажем правильный порядок: `w.Header().Set(...)` -> `w.WriteHeader(201)` -> `w.Write(...)`.\n2. Продемонстрируем ошибку «superfluous response.WriteHeader call», возникающую при попытке вызвать `WriteHeader` после записи.\n3. Проверим статус-коды клиентом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc correctHandler(w http.ResponseWriter, r *http.Request) {\n\t// 1. Сначала заголовки\n\tw.Header().Set("Content-Type", "application/json")\n\t// 2. Затем статус-код\n\tw.WriteHeader(http.StatusCreated)\n\t// 3. И только потом тело ответа!\n\t_, _ = w.Write([]byte(`{"result":"created"}`))\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/correct", correctHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/correct")\n\tdefer resp.Body.Close()\n\n\tfmt.Printf("[Правильный вызов] Статус: %d %s\\n", resp.StatusCode, resp.Status)\n\tfmt.Printf("[Заголовок]        Content-Type: %s\\n", resp.Header.Get("Content-Type"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Правильный вызов] Статус: 201 201 Created\n# [Заголовок]        Content-Type: application/json'}], 'under_the_hood': 'Когда байты отправлены в сетевой стек, TCP-пакет с заголовками уже ушел на сетевую карту. Попытка повторно вызвать `w.WriteHeader(...)` вызовет предупреждение в stderr: `http: superfluous response.WriteHeader call`.', 'pitfalls': 'Функция `http.Error(w, msg, code)` сама вызывает `WriteHeader(code)` и `w.Write()`. После вызова `http.Error` необходимо сразу делать `return`, иначе хендлер продолжит выполнение и попытается отправить ответ повторно.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит под капотом, если вызвать w.Header().Set(...) после вызова w.WriteHeader(...)?»\n**Ответ:** Такой заголовок просто проигнорируется и не дойдет до клиента, поскольку заголовки уже сериализованы и отправлены в сокет в момент вызова `WriteHeader` (или первого `Write`). Исключение — HTTP/2 Trailers, которые настраиваются особым образом.'}, {'num': 21, 'title': 'Генерация сквозного Request ID и проброс через контекст и заголовки ответа', 'task': "Напиши **Request ID middleware**: генерируй UUID (или `rand`) для каждого запроса, добавь в контекст. Все логи внутри handler'а должны включать этот ID. Добавь заголовок `X-Request-ID` в ответ.", 'theory': 'Сквозной идентификатор запроса (Correlation ID / Request ID): при поступлении HTTP-запроса middleware проверяет входящий заголовок `X-Request-ID` (если запрос пришел от вышестоящего прокси) либо генерирует новый уникальный ID. Этот ID помещается в `context.Context` и возвращается клиенту в заголовке ответа, позволяя связать все логи распределенной системы.', 'step_by_step': '1. Создадим тип ключа контекста `type reqIDKey struct{}`.\n2. Реализуем `RequestIDMiddleware`, устанавливающий `w.Header().Set("X-Request-ID", id)`.\n3. В обработчике извлечем ID из контекста и залогируем действие.\n4. Проверим наличие заголовка в ответе клиенту.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"crypto/rand"\n\t"encoding/hex"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype contextKey struct{}\n\nvar requestIDKey = contextKey{}\n\nfunc generateID() string {\n\tb := make([]byte, 8)\n\t_, _ = rand.Read(b)\n\treturn hex.EncodeToString(b)\n}\n\nfunc RequestIDMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\treqID := r.Header.Get("X-Request-ID")\n\t\tif reqID == "" {\n\t\t\treqID = generateID()\n\t\t}\n\n\t\tw.Header().Set("X-Request-ID", reqID)\n\t\tctx := context.WithValue(r.Context(), requestIDKey, reqID)\n\t\tnext.ServeHTTP(w, r.WithContext(ctx))\n\t})\n}\n\nfunc apiHandler(w http.ResponseWriter, r *http.Request) {\n\treqID, _ := r.Context().Value(requestIDKey).(string)\n\tfmt.Printf("[LOG] [ReqID: %s] Обработка платежного запроса...\\n", reqID)\n\tfmt.Fprint(w, "OK")\n}\n\nfunc main() {\n\thandler := RequestIDMiddleware(http.HandlerFunc(apiHandler))\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\tresp, err := http.Get(ts.URL)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tfmt.Printf("[Client] Получен ответ с X-Request-ID: %s\\n", resp.Header.Get("X-Request-ID"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [LOG] [ReqID: 9a4f21e0b5c178ad] Обработка платежного запроса...\n# [Client] Получен ответ с X-Request-ID: 9a4f21e0b5c178ad'}], 'under_the_hood': 'Использование `crypto/rand` гарантирует криптографическую стойкость идентификатора без использования тяжелых внешних библиотек.', 'pitfalls': 'Если клиент уже прислал свой `X-Request-ID`, его стоит сохранить и пробросить дальше, а не перезаписывать новым случайным ID.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между W3C Traceparent и X-Request-ID?»\n**Ответ:** `X-Request-ID` — исторический стандарт одного идентификатора запроса. `Traceparent` (спецификация W3C / OpenTelemetry) содержит 4 поля: версию, 128-битный Trace ID, 64-битный Parent Span ID и флаги трейсинга, поддерживая иерархию распределенных вызовов.'}, {'num': 22, 'title': 'Структурированный логгер HTTP-запросов с замером RTT и статуса', 'task': 'Напиши **HTTP middleware** `LoggingMiddleware(next http.Handler) http.Handler`, который логирует метод, путь, статус-код и время выполнения. Используй `http.HandlerFunc` и оборачивай handler.', 'theory': 'Качественный HTTP Access Logger фиксирует ключевые метрики каждого запроса: метод, URI, статус ответа и время выполнения (Latency/RTT). Для перехвата статуса используется паттерн Response Recorder.', 'step_by_step': '1. Создадим структуру-обертку `statusRecorder`.\n2. В `LoggingMiddleware` засечем время до и после `next.ServeHTTP`.\n3. Распечатаем форматированную строку лога.\n4. Проверим работу на успешном и ошибочном запросах.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\ntype statusRecorder struct {\n\thttp.ResponseWriter\n\tstatus int\n}\n\nfunc (rec *statusRecorder) WriteHeader(code int) {\n\trec.status = code\n\trec.ResponseWriter.WriteHeader(code)\n}\n\nfunc LoggingMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tstart := time.Now()\n\t\trec := &statusRecorder{ResponseWriter: w, status: http.StatusOK}\n\n\t\tnext.ServeHTTP(rec, r)\n\n\t\tduration := time.Since(start)\n\t\tfmt.Printf("[ACCESS] %-6s %-12s | Status: %d | Duration: %v\\n",\n\t\t\tr.Method, r.URL.Path, rec.status, duration.Round(time.Microsecond))\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\tw.WriteHeader(http.StatusOK)\n\t})\n\tmux.HandleFunc("/error", func(w http.ResponseWriter, r *http.Request) {\n\t\ttime.Sleep(2 * time.Millisecond)\n\t\thttp.Error(w, "internal issue", http.StatusInternalServerError)\n\t})\n\n\tlogged := LoggingMiddleware(mux)\n\tts := httptest.NewServer(logged)\n\tdefer ts.Close()\n\n\tres1, _ := http.Get(ts.URL + "/users")\n\tres1.Body.Close()\n\n\tres2, _ := http.Get(ts.URL + "/error")\n\tres2.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [ACCESS] GET    /users       | Status: 200 | Duration: 5ms\n# [ACCESS] GET    /error       | Status: 500 | Duration: 2ms'}], 'under_the_hood': 'Поскольку `statusRecorder` анонимно встраивает `http.ResponseWriter`, все остальные методы (например, `Write`, `Header`) автоматически делегируются исходному объекту ответа.', 'pitfalls': 'Если обработчик не вызывает `WriteHeader` явно, `rec.status` останется равным дефолтному значению, поэтому поле инициализируют значением `http.StatusOK`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему наивная обертка над ResponseWriter может сломать HTTP Hijacking или Flusher?»\n**Ответ:** Интерфейсы `http.Hijacker` и `http.Flusher` являются опциональными. Если обертка просто встраивает `ResponseWriter` и не реализует эти методы явно, проверка типа `w.(http.Flusher)` вернет false, сломав стриминг SSE или WebSocket.'}, {'num': 23, 'title': 'Ловушка порядка установки заголовков: исправление Content-Type до вызова Write', 'task': '**[Каверзный кейс]**: Верни JSON-ответ, но забудь установить заголовок `Content-Type: application/json` ДО вызова `w.Write()`. Пойми, почему заголовок не установится (Go вызывает `WriteHeader(200)` автоматически при первом `Write()`). Исправь порядок.', 'theory': 'При первом обращении к `w.Write(bytes)` HTTP-движок Go проверяет внутренний флаг `wroteHeader`. Если он `false`, Go автоматически делает `w.WriteHeader(http.StatusOK)` и сбрасывает все текущие заголовки в сокет. Любая последующая модификация `w.Header().Set(...)` молча игнорируется.', 'step_by_step': '1. Создадим некорректный хендлер, где `Header().Set` вызывается ПОСЛЕ `w.Write`.\n2. Покажем, что клиент получает `text/plain` вместо `application/json`.\n3. Исправим код, установив заголовок до вызова `w.Write`.\n4. Проверим корректный `Content-Type`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc brokenHandler(w http.ResponseWriter, r *http.Request) {\n\t// ОШИБКА: запись в тело ДО настройки заголовков!\n\t_, _ = w.Write([]byte(`{"status":"ok"}`))\n\tw.Header().Set("Content-Type", "application/json") // Проигнорируется!\n}\n\nfunc fixedHandler(w http.ResponseWriter, r *http.Request) {\n\t// ПРАВИЛЬНО: сначала заголовки, затем запись!\n\tw.Header().Set("Content-Type", "application/json")\n\t_, _ = w.Write([]byte(`{"status":"ok"}`))\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/broken", brokenHandler)\n\tmux.HandleFunc("/fixed", fixedHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tres1, _ := http.Get(ts.URL + "/broken")\n\tres1.Body.Close()\n\tfmt.Println("Broken Content-Type:", res1.Header.Get("Content-Type"))\n\n\tres2, _ := http.Get(ts.URL + "/fixed")\n\tres2.Body.Close()\n\tfmt.Println("Fixed Content-Type: ", res2.Header.Get("Content-Type"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Broken Content-Type: text/plain; charset=utf-8\n# Fixed Content-Type:  application/json'}], 'under_the_hood': 'Внутри `w.Write()` вызывается функция `http.DetectContentType(p[:512])`. Для строки `{"status":"ok"}` эвристика Go выбирает `text/plain`, если явный `Content-Type` не был выставлен заранее.', 'pitfalls': 'То же самое касается `w.WriteHeader(code)` — после первого `w.Write()` код ответа уже невозможно изменить на 400 или 500.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему хендлер обязан возвращать управление сразу после вызова http.Error?»\n**Ответ:** `http.Error` вызывает `WriteHeader` и записывает текст ошибки в `w`. Если хендлер не сделает `return`, последующий код попытается записать тело или статус, вызвав панику или ошибку в логах сервера `superfluous WriteHeader`.'}, {'num': 24, 'title': 'Раздача статических файлов с помощью встроенного http.FileServer', 'task': 'Раздавай статические файлы (например, HTML или картинки) из папки `./static` с помощью `http.FileServer(http.Dir("./static"))`.', 'theory': '`http.FileServer(root)` реализует полноценный веб-сервер статики:\n- Автоматически рассчитывает `Content-Type` по расширению файла.\n- Поддерживает заголовки кэширования `ETag` и `Last-Modified` (HTTP 304 Not Modified).\n- Поддерживает частичные диапазоны байтов `Accept-Ranges: bytes` (HTTP 206 Partial Content).\n- Исключает уязвимости Directory Traversal (`../../etc/passwd`).', 'step_by_step': '1. Создадим временную директорию с тестовым файлом `style.css`.\n2. Настроим `http.FileServer(http.Dir(dir))`.\n3. Запросим файл через HTTP GET.\n4. Проверим статус 200 и заголовок `Content-Type`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"path/filepath"\n)\n\nfunc main() {\n\ttempDir, err := os.MkdirTemp("", "static_test_*")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer os.RemoveAll(tempDir)\n\n\t// Создаем тестовый статический файл\n\tcssPath := filepath.Join(tempDir, "style.css")\n\t_ = os.WriteFile(cssPath, []byte("body { background: #000; color: #fff; }"), 0644)\n\n\tfileServer := http.FileServer(http.Dir(tempDir))\n\tts := httptest.NewServer(fileServer)\n\tdefer ts.Close()\n\n\tresp, err := http.Get(ts.URL + "/style.css")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer resp.Body.Close()\n\n\tbody, _ := io.ReadAll(resp.Body)\n\tfmt.Printf("[Status]       %d\\n", resp.StatusCode)\n\tfmt.Printf("[Content-Type] %s\\n", resp.Header.Get("Content-Type"))\n\tfmt.Printf("[Body]         %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status]       200\n# [Content-Type] text/css; charset=utf-8\n# [Body]         body { background: #000; color: #fff; }'}], 'under_the_hood': '`http.Dir` реализует интерфейс `http.FileSystem`. При обращении к директории без файла `FileServer` отдает сгенерированный HTML со списком файлов или `index.html`, если он есть.', 'pitfalls': 'Если в продакшене не отключить листинг директорий, пользователи смогут просматривать структуру всех файлов на сервере.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в Go 1.16+ встроить статические файлы прямо в бинарник (Single Binary Deployment)?»\n**Ответ:** Использовать пакет `embed` и директиву `//go:embed static/* var staticFS embed.FS`. Затем обернуть её через `http.FS(staticFS)` и передать в `http.FileServer`.'}, {'num': 25, 'title': 'Управление сессионными Cookie с флагами безопасности HttpOnly, Secure и SameSite', 'task': 'Реализуйте хендлер, который устанавливает `HttpOnly` и `Secure` Cookie в браузер клиента.', 'theory': 'Защита аутентификационных сессий требует обязательной установки атрибутов безопасности кук:\n- `HttpOnly: true` — запрещает доступ к cookie через JavaScript (`document.cookie`), блокируя кражу сессии при XSS-атаках.\n- `Secure: true` — предписывает передавать cookie исключительно по зашифрованному протоколу HTTPS.\n- `SameSite: http.SameSiteStrictMode` — защищает от межсайтовой подделки запросов (CSRF).', 'step_by_step': '1. Создадим структуру `http.Cookie` со всеми параметрами безопасности.\n2. Вызовем `http.SetCookie(w, &cookie)`.\n3. Клиентом прочитаем заголовок `Set-Cookie` из ответа.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"time"\n)\n\nfunc setSessionHandler(w http.ResponseWriter, r *http.Request) {\n\tcookie := http.Cookie{\n\t\tName:     "session_token",\n\t\tValue:    "xyz789_secure_token",\n\t\tPath:     "/",\n\t\tExpires:  time.Now().Add(24 * time.Hour),\n\t\tMaxAge:   86400,\n\t\tHttpOnly: true,                  // Защита от XSS\n\t\tSecure:   true,                  // Только HTTPS\n\t\tSameSite: http.SameSiteLaxMode,  // Защита от CSRF\n\t}\n\n\thttp.SetCookie(w, &cookie)\n\tw.WriteHeader(http.StatusOK)\n\tfmt.Fprint(w, "Сессионная кука успешно установлена")\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(setSessionHandler))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tdefer resp.Body.Close()\n\n\tcookies := resp.Cookies()\n\tfor _, c := range cookies {\n\t\tfmt.Printf("Кука: %s=%s | HttpOnly: %v | Secure: %v | SameSite: %v\\n",\n\t\t\tc.Name, c.Value, c.HttpOnly, c.Secure, c.SameSite)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Кука: session_token=xyz789_secure_token | HttpOnly: true | Secure: true | SameSite: 2'}], 'under_the_hood': '`http.SetCookie` форматирует строку заголовка `Set-Cookie` по спецификации RFC 6265 и добавляет её в `w.Header().Add("Set-Cookie", ...)`.', 'pitfalls': 'Для удаления куки на клиенте необходимо установить `MaxAge: -1` или истекшую дату в поле `Expires`.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между SameSite=Strict и SameSite=Lax?»\n**Ответ:** При `SameSite=Strict` cookie никогда не отправляется при переходе со стороннего сайта (даже по обычной ссылке). При `SameSite=Lax` кука отправляется только при безопасных навигационных переходах верхнего уровня (Top-Level GET navigation), обеспечивая баланс безопасности и UX.'}, {'num': 26, 'title': 'Спецификация роутов Go 1.22+: разграничение методов и PathValue', 'task': '**Новый роутинг (Go 1.22+)**: Начиная с Go 1.22 стандартный роутер стал мощным. Зарегистрируй роут с указанием метода и переменной пути: `mux.HandleFunc("GET /users/{id}", handler)`. Внутри функции достань `id` через `r.PathValue("id")`.', 'theory': 'Новый роутинг в Go 1.22 решает большинство задач без необходимости сторонних библиотек:\n- `"GET /items/{id}"` матчит только GET-запросы.\n- `"POST /items"` матчит только POST-запросы.\n- Метод `r.PathValue("id")` возвращает сегмент пути по имени метки.', 'step_by_step': '1. Создадим `mux := http.NewServeMux()`.\n2. Зарегистрируем `"GET /orders/{order_id}"`.\n3. Извлечем значение через `r.PathValue("order_id")`.\n4. Отправим проверочный запрос.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc getOrderHandler(w http.ResponseWriter, r *http.Request) {\n\torderID := r.PathValue("order_id")\n\tfmt.Fprintf(w, "Заказ #%s находится в обработке", orderID)\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("GET /orders/{order_id}", getOrderHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/orders/ORD-7744")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("Ответ сервера: %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ответ сервера: Заказ #ORD-7744 находится в обработке'}], 'under_the_hood': 'Под капотом `r.PathValue` обращается к встроенной мапе параметров пути в `http.Request`, которая заполняется роутером в O(1).', 'pitfalls': 'Имена переменных пути чувствительны к регистру: `{id}` и `{ID}` — разные ключи.', 'bigtech_interview': '**Вопрос с собеседования:** «Как в Go 1.22+ разрешаются конфликты маршрутов (Precedence Rules)?»\n**Ответ:** Более точный маршрут всегда имеет больший приоритет над менее точным (Exact match > Path with variable > Wildcard/Subtree). Если два маршрута эквивалентны по специфичности, `ServeMux` запаникует на этапе регистрации.'}, {'num': 27, 'title': 'Реализация HTTP Basic Auth Middleware со стандартом RFC 7617', 'task': 'Напиши **HTTP Basic Auth middleware**: проверяй `Authorization: Basic <base64>`. Декодируй через `base64.StdEncoding.DecodeString`. Если логин/пароль неверны — `401` с заголовком `WWW-Authenticate: Basic realm="Restricted"`.', 'theory': 'HTTP Basic Authentication (RFC 7617) кодирует пару `username:password` в Base64. В стандартной библиотеке Go для этого есть готовый метод `r.BasicAuth()`, который автоматически декодирует заголовок и возвращает пользователя, пароль и булев флаг наличия заголовка.', 'step_by_step': '1. Напишем `BasicAuthMiddleware`.\n2. Используем `r.BasicAuth()` для извлечения креденшелов.\n3. При несовпадении вернем заголовок `WWW-Authenticate: Basic realm="Restricted"` и код 401.\n4. Протестируем вызовы без авторизации и с верным паролем.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"crypto/subtle"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc BasicAuthMiddleware(expectedUser, expectedPass string, next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tuser, pass, ok := r.BasicAuth()\n\t\tif !ok || subtle.ConstantTimeCompare([]byte(user), []byte(expectedUser)) != 1 ||\n\t\t\tsubtle.ConstantTimeCompare([]byte(pass), []byte(expectedPass)) != 1 {\n\t\t\tw.Header().Set("WWW-Authenticate", `Basic realm="Restricted"`)\n\t\t\thttp.Error(w, "Unauthorized", http.StatusUnauthorized)\n\t\t\treturn\n\t\t}\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc adminDashboard(w http.ResponseWriter, r *http.Request) {\n\tfmt.Fprint(w, "Секретная панель управления")\n}\n\nfunc main() {\n\thandler := BasicAuthMiddleware("admin", "super-secret-pass", http.HandlerFunc(adminDashboard))\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\t// 1. Без авторизации\n\tr1, _ := http.Get(ts.URL)\n\tfmt.Printf("[1. Запрос] Status: %d, Header: %s\\n", r1.StatusCode, r1.Header.Get("WWW-Authenticate"))\n\tr1.Body.Close()\n\n\t// 2. С правильной авторизацией\n\treq, _ := http.NewRequest(http.MethodGet, ts.URL, nil)\n\treq.SetBasicAuth("admin", "super-secret-pass")\n\tr2, _ := http.DefaultClient.Do(req)\n\tb2, _ := io.ReadAll(r2.Body)\n\tr2.Body.Close()\n\tfmt.Printf("[2. Запрос] Status: %d, Body: %s\\n", r2.StatusCode, string(b2))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [1. Запрос] Status: 401, Header: Basic realm="Restricted"\n# [2. Запрос] Status: 200, Body: Секретная панель управления'}], 'under_the_hood': '`subtle.ConstantTimeCompare` предотвращает атаки по времени (Timing Attacks), сравнивая срезы байтов за константное время вне зависимости от того, в каком символе расхождение.', 'pitfalls': 'Basic Auth передает логин и пароль в открытом виде (Base64 — это кодирование, а не шифрование!). Использование Basic Auth допустимо строго поверх защищенного канала HTTPS.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему строки паролей в middleware сравнивают через subtle.ConstantTimeCompare, а не через оператор ==?»\n**Ответ:** Обычное сравнение строк `==` прерывается на первом несовпадающем байте. Измеряя наносекундное время ответа сервера, злоумышленник может посимвольно подобрать правильный пароль. `ConstantTimeCompare` выполняется строго за фиксированное время.'}, {'num': 28, 'title': 'Архитектурная концепция Middleware: сигнатура и функция высшего порядка', 'task': 'Напишите концепцию Middleware: функцию, которая принимает `http.Handler` и возвращает новый `http.Handler`, оборачивая логику.', 'theory': 'Middleware в Go — это функция высшего порядка следующей сигнатуры:\n`func(http.Handler) http.Handler`\nОна декорирует поведение входного обработчика, добавляя логику до и после вызова `next.ServeHTTP`.', 'step_by_step': '1. Создадим тип `type Middleware func(http.Handler) http.Handler`.\n2. Напишем тестовое middleware, добавляющее заголовок `X-Powered-By: Golang`.\n3. Обернем конечный хендлер.\n4. Проверим заголовок в ответе.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype Middleware func(http.Handler) http.Handler\n\nfunc HeaderDecoratorMiddleware(headerName, headerVal string) Middleware {\n\treturn func(next http.Handler) http.Handler {\n\t\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\t\tw.Header().Set(headerName, headerVal)\n\t\t\tnext.ServeHTTP(w, r)\n\t\t})\n\t}\n}\n\nfunc main() {\n\thandler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Core Application Response")\n\t})\n\n\tmw := HeaderDecoratorMiddleware("X-Platform", "Go-Workout-Engine")\n\tdecoratedHandler := mw(handler)\n\n\tts := httptest.NewServer(decoratedHandler)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tdefer resp.Body.Close()\n\n\tfmt.Printf("Статус: %d\\n", resp.StatusCode)\n\tfmt.Printf("X-Platform заголовок: %s\\n", resp.Header.Get("X-Platform"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Статус: 200\n# X-Platform заголовок: Go-Workout-Engine'}], 'under_the_hood': 'Замыкание удерживает параметры `headerName` и `headerVal`, позволяя создавать параметризованные middleware фабрики.', 'pitfalls': 'Не изменяйте глобальные переменные внутри функции-обработчика middleware, так как она вызывается конкурентно в сотнях параллельных горутин.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать функцию Chain(middlewares ...Middleware) Middleware для сборки цепочки без вложенных скобок?»\n**Ответ:** Написать цикл, сворачивающий срез middleware справа налево:\n```go\nfunc Chain(middlewares ...Middleware) Middleware {\n    return func(final http.Handler) http.Handler {\n        for i := len(middlewares) - 1; i >= 0; i-- {\n            final = middlewares[i](final)\n        }\n        return final\n    }\n}\n```'}, {'num': 29, 'title': 'Хендлер поиска с фильтрацией по query-параметрам q и limit', 'task': 'Напиши **handler с query-параметрами**: `GET /search?q=golang&limit=10`. Извлеки `q` и `limit` через `r.URL.Query().Get()`. Верни JSON с результатами (заглушками).', 'theory': 'Поисковые эндпоинты типично принимают текстовый запрос `q` и целочисленный лимит `limit`. При извлечении числовых параметров необходимо задавать дефолтные значения и валидировать максимальный допустимый размер лимита во избежание DoS-атак.', 'step_by_step': '1. Зарегистрируем `"GET /search"`.\n2. Считаем параметр `q` и валидируем, что он не пустой.\n3. Спарсим `limit` через `strconv.Atoi` (дефолт 10, максимум 100).\n4. Вернем JSON со списком результатов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strconv"\n)\n\ntype SearchResult struct {\n\tQuery string   `json:"query"`\n\tLimit int      `json:"limit"`\n\tItems []string `json:"items"`\n}\n\nfunc searchHandler(w http.ResponseWriter, r *http.Request) {\n\tq := r.URL.Query().Get("q")\n\tif q == "" {\n\t\thttp.Error(w, "параметр \'q\' обязателен", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tlimit := 10\n\tif lStr := r.URL.Query().Get("limit"); lStr != "" {\n\t\tif val, err := strconv.Atoi(lStr); err == nil && val > 0 && val <= 100 {\n\t\t\tlimit = val\n\t\t}\n\t}\n\n\tres := SearchResult{\n\t\tQuery: q,\n\t\tLimit: limit,\n\t\tItems: []string{"Результат #1 по " + q, "Результат #2 по " + q},\n\t}\n\n\tw.Header().Set("Content-Type", "application/json")\n\t_ = json.NewEncoder(w).Encode(res)\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("GET /search", searchHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/search?q=golang&limit=2")\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Println(string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# {"query":"golang","limit":2,"items":["Результат #1 по golang","Результат #2 по golang"]}'}], 'under_the_hood': '`url.Values.Get` автоматически выполняет URL-декодирование символов (например, `%20` -> пробел).', 'pitfalls': 'Никогда не доверяйте значению `limit` от клиента напрямую без верхней границы (например, `<= 100`), иначе клиент запросит `limit=10000000` и уронит базу данных.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в высоконагруженных API для пагинации предпочитают Cursor-based вместо Limit/Offset?»\n**Ответ:** При больших значениях `OFFSET 1000000` реляционная СУБД вынуждена физически просканировать и отбросить миллион строк. Курсорная пагинация (`WHERE id > last_seen_id LIMIT 20`) использует индекс B-Tree и работает за константное время $O(\\log N)$.**'}, {'num': 30, 'title': 'Custom http.ResponseWriter для точного захвата реального статус-кода и размера ответа', 'task': 'Напиши **custom http.ResponseWriter** для захвата статус-кода: `type responseRecorder struct { status int; http.ResponseWriter }`. Переопредели `WriteHeader`. Используй в middleware для логирования реального статуса (даже если handler его не пишет явно, по умолчанию 200).', 'theory': 'Стандартный интерфейс `http.ResponseWriter` не имеет метода `StatusCode() int` для чтения уже отправленного кода. Чтобы логгер или сборщик метрик Prometheus мог зафиксировать статус ответа, создают структуру-шпион, оборачивающую исходный `ResponseWriter` и перехватывающую вызовы `WriteHeader` и `Write`.', 'step_by_step': '1. Создадим структуру `ResponseRecorder` с полями `status` и `bytesWritten`.\n2. Переопределим методы `WriteHeader(int)` и `Write([]byte) (int, error)`.\n3. Напишем middleware, логирующее точный статус и число байт.\n4. Проверим работу на маршруте без явного вызова `WriteHeader`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\ntype ResponseRecorder struct {\n\thttp.ResponseWriter\n\tStatusCode   int\n\tBytesWritten int\n}\n\nfunc (r *ResponseRecorder) WriteHeader(code int) {\n\tr.StatusCode = code\n\tr.ResponseWriter.WriteHeader(code)\n}\n\nfunc (r *ResponseRecorder) Write(b []byte) (int, error) {\n\tn, err := r.ResponseWriter.Write(b)\n\tr.BytesWritten += n\n\treturn n, err\n}\n\nfunc MetricLogger(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\trec := &ResponseRecorder{\n\t\t\tResponseWriter: w,\n\t\t\tStatusCode:     http.StatusOK, // Дефолтный статус при вызове Write\n\t\t}\n\n\t\tnext.ServeHTTP(rec, r)\n\n\t\tfmt.Printf("[Метрики] Путь: %-6s | Статус: %d | Байт отдано: %d\\n",\n\t\t\tr.URL.Path, rec.StatusCode, rec.BytesWritten)\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/implicit", func(w http.ResponseWriter, r *http.Request) {\n\t\t// Не вызываем WriteHeader явно -> статус 200\n\t\t_, _ = w.Write([]byte("Hello Implicit"))\n\t})\n\tmux.HandleFunc("/explicit", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.WriteHeader(http.StatusAccepted)\n\t\t_, _ = w.Write([]byte("Accepted"))\n\t})\n\n\tserver := httptest.NewServer(MetricLogger(mux))\n\tdefer server.Close()\n\n\tres1, _ := http.Get(server.URL + "/implicit")\n\tres1.Body.Close()\n\n\tres2, _ := http.Get(server.URL + "/explicit")\n\tres2.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Метрики] Путь: /implicit | Статус: 200 | Байт отдано: 14\n# [Метрики] Путь: /explicit | Статус: 202 | Байт отдано: 8'}], 'under_the_hood': 'Если хендлер просто вызывает `w.Write()`, поле `StatusCode` останется равным `http.StatusOK`, что полностью отражает поведение спецификации HTTP в Go.', 'pitfalls': 'Обязательно сохраняйте дефолтное значение `http.StatusOK` в `StatusCode`, иначе при записи без явного `WriteHeader` статус ошибочно залогируется как 0.', 'bigtech_interview': '**Вопрос с собеседования:** «Как обернуть ResponseWriter и не потерять поддержку http.Hijacker для WebSocket?»\n**Ответ:** Реализовать метод `Hijack() (net.Conn, *bufio.ReadWriter, error)` на структуре `ResponseRecorder`, который проверяет приведение внутреннего `r.ResponseWriter.(http.Hijacker)` и вызывает его.'}, {'num': 31, 'title': 'Файловый сервер с StripPrefix и тестирование защиты от Directory Traversal', 'task': 'Напиши **file server**: `http.FileServer(http.Dir("./static"))`. Настрой обработку `/static/` через `http.StripPrefix`. Проверь доступ к файлам, попробуй directory traversal (`../../etc/passwd`) — покажи, что `http.FileServer` защищён от этого.', 'theory': 'При монтировании файлового сервера на префикс (например, `/static/`) необходимо убирать этот префикс из пути запроса с помощью `http.StripPrefix("/static/", fileServer)`, иначе сервер будет искать файлы по пути `./static/static/file.txt`.\nРантайм Go нормализует путь с помощью `path.Clean` и предотвращает любые попытки выхода за пределы корня через `../`.', 'step_by_step': '1. Создадим тестовую папку `test_static` с файлом `data.txt`.\n2. Зарегистрируем маршрут `/static/` с `http.StripPrefix`.\n3. Проверим чтение легитимного файла.\n4. Отправим запрос с Path Traversal `../../` и убедимся, что он пресекается.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"path/filepath"\n)\n\nfunc main() {\n\ttempDir, _ := os.MkdirTemp("", "sec_static_*")\n\tdefer os.RemoveAll(tempDir)\n\n\t_ = os.WriteFile(filepath.Join(tempDir, "data.txt"), []byte("Public Static Content"), 0644)\n\n\tmux := http.NewServeMux()\n\tfileHandler := http.StripPrefix("/static/", http.FileServer(http.Dir(tempDir)))\n\tmux.Handle("/static/", fileHandler)\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// 1. Легитимный запрос\n\tres1, _ := http.Get(ts.URL + "/static/data.txt")\n\tbody, _ := io.ReadAll(res1.Body)\n\tres1.Body.Close()\n\tfmt.Printf("[GET /static/data.txt] Status: %d, Content: %s\\n", res1.StatusCode, string(body))\n\n\t// 2. Попытка Directory Traversal\n\tres2, _ := http.Get(ts.URL + "/static/../../../../etc/passwd")\n\tres2.Body.Close()\n\tfmt.Printf("[GET Traversal Attack] Status: %d (Сервер защищен от выхода из корня!)\\n", res2.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [GET /static/data.txt] Status: 200, Content: Public Static Content\n# [GET Traversal Attack] Status: 404 (Сервер защищен от выхода из корня!)'}], 'under_the_hood': '`http.Dir.Open` проверяет путь через `filepath.Rel` и отклоняет любые пути, начинающиеся с `..` или содержащие ссылки вне базового каталога.', 'pitfalls': 'Если забыть замыкающий слэш в `http.StripPrefix("/static/", ...)`, префикс будет обрезан некорректно.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в продакшене отдачу тяжелой статики (картинки, видео) переносят на Nginx или S3/CDN вместо Go FileServer?»\n**Ответ:** Nginx использует системный вызов `sendfile()` (zero-copy передача из дискового кэша ядра Linux напрямую в сетевую карту) и снимает нагрузку с рантайма и сборщика мусора Go. CDN кэширует контент на периферии ближе к пользователю.'}, {'num': 32, 'title': 'Middleware Recovery: перехват паник, логирование стека и возврат 500 Internal Error', 'task': 'Создайте middleware `Recovery`, который перехватывает `panic` внутри хендлеров, логирует стек-трейс и возвращает клиенту HTTP 500, не роняя весь сервер.', 'theory': 'Хотя рантайм `net/http` изолирует горутины и сервер не падает целиком при `panic()`, клиент без кастомного recovery получает внезапно оборванный TCP-сокет без HTTP-статуса и без форматированного тела ответа. Middleware `Recovery` вызывает `recover()` в `defer`, логирует стек через `runtime/debug.Stack()` и аккуратно возвращает клиенту статус 500.', 'step_by_step': '1. Напишем `RecoveryMiddleware` с блоком `defer func() { if err := recover(); ... }`.\n2. Извлечем стек вызовов через `debug.Stack()`.\n3. Вернем клиенту JSON-ошибку 500.\n4. Протестируем паникующий обработчик.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"runtime/debug"\n)\n\nfunc RecoveryMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tdefer func() {\n\t\t\tif err := recover(); err != nil {\n\t\t\t\t// Логируем стек-трейс паники\n\t\t\t\tfmt.Printf("[CRITICAL PANIC RECOVERED] Причина: %v\\nСтек:\\n%s\\n", err, string(debug.Stack()))\n\n\t\t\t\tw.Header().Set("Content-Type", "application/json")\n\t\t\t\tw.WriteHeader(http.StatusInternalServerError)\n\t\t\t\t_, _ = w.Write([]byte(`{"error":"internal server error","code":500}`))\n\t\t\t}\n\t\t}()\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc panicHandler(w http.ResponseWriter, r *http.Request) {\n\tvar ptr *int\n\t*ptr = 42 // Намеренная паника: разыменование nil-указателя!\n}\n\nfunc main() {\n\thandler := RecoveryMiddleware(http.HandlerFunc(panicHandler))\n\tts := httptest.NewServer(handler)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tbody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("[Ответ клиенту] Status: %d\\n", resp.StatusCode)\n\tfmt.Printf("[Тело ответа]    %s\\n", string(body))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [CRITICAL PANIC RECOVERED] Причина: runtime error: invalid memory address or nil pointer dereference\n# [Ответ клиенту] Status: 500\n# [Тело ответа]    {"error":"internal server error","code":500}'}], 'under_the_hood': '`recover()` работает только в том случае, если вызывается напрямую внутри отложенной функции `defer`. Он останавливает панику текущей горутины.', 'pitfalls': 'Если паника произошла внутри отдельной горутины, запущенной из хендлера (`go func() { panic(...) }()`), middleware верхнего уровня ее НЕ поймает, и весь процесс приложения аварийно завершится!', 'bigtech_interview': '**Вопрос с собеседования:** «Почему паника в фоновой горутине `go func(){...}()` роняет весь Go-процесс, даже если на сервере есть Recovery Middleware?»\n**Ответ:** Паника привязана к стеку конкретной горутины. `defer/recover` перехватывает панику только в пределах своей горутины. Фоновая горутина имеет собственный изолированный стек, и неуправляемая паника в ней приводит к `fatal error` и крашу всего процесса.'}, {'num': 33, 'title': 'Хендлер скачивания файлов с заголовком Content-Disposition attachment', 'task': 'Создай обработчик, который скачивает файл клиенту. Установи заголовок `Content-Disposition: attachment; filename="file.txt"` и отправь байты в `w`.', 'theory': 'Заголовок `Content-Disposition: attachment; filename="..."` указывает веб-браузеру не открывать файл во встроенном просмотрщике, а вызвать системное диалоговое окно «Сохранить файл как...» с заданным именем.', 'step_by_step': '1. Создадим обработчик `/download`.\n2. Установим заголовки `Content-Disposition`, `Content-Type` и `Content-Length`.\n3. Отправим бинарные или текстовые данные в `w`.\n4. Проверим заголовки клиентом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc downloadHandler(w http.ResponseWriter, r *http.Request) {\n\tfileContent := []byte("Финансовый отчет за 2026 год. Конфиденциально.")\n\n\tw.Header().Set("Content-Disposition", `attachment; filename="report-2026.txt"`)\n\tw.Header().Set("Content-Type", "text/plain; charset=utf-8")\n\tw.Header().Set("Content-Length", fmt.Sprintf("%d", len(fileContent)))\n\n\tw.WriteHeader(http.StatusOK)\n\t_, _ = w.Write(fileContent)\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(downloadHandler))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tdefer resp.Body.Close()\n\n\tfmt.Printf("[Status]              %d\\n", resp.StatusCode)\n\tfmt.Printf("[Content-Disposition] %s\\n", resp.Header.Get("Content-Disposition"))\n\tfmt.Printf("[Content-Length]      %s байт\\n", resp.Header.Get("Content-Length"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status]              200\n# [Content-Disposition] attachment; filename="report-2026.txt"\n# [Content-Length]      79 байт'}], 'under_the_hood': 'Если используется значение `inline` вместо `attachment`, браузер пытается отобразить файл прямо на вкладке (для PDF, PNG, MP4).', 'pitfalls': "В именах файлов с не-ASCII символами (кириллица, пробелы) по стандарту RFC 5987 следует использовать кодирование: `filename*=UTF-8''%D0%BE...`.", 'bigtech_interview': '**Вопрос с собеседования:** «Как безопасно отдавать файлы с диска пользователям, защитившись от XSS при загрузке вредоносного HTML?»\n**Ответ:** Устанавливать заголовки `Content-Disposition: attachment`, `Content-Type: application/octet-stream` и `X-Content-Type-Options: nosniff`, запрещая браузеру интерпретировать загружаемый файл как исполняемый HTML/JavaScript.'}, {'num': 34, 'title': 'Прием и сохранение файлов через multipart/form-data с ParseMultipartForm', 'task': 'Напиши **upload handler**: `POST /upload`. Парсь `multipart/form-data` через `r.ParseMultipartForm(10 << 20)` (10MB). Сохрани загруженный файл на диск. Верни имя сохранённого файла.', 'theory': 'Загрузка файлов на сервер:\n1. `r.ParseMultipartForm(maxMemory)` парсит тело запроса, удерживая в RAM до `maxMemory` байт, а остальное сбрасывая во временные файлы на диск.\n2. `r.FormFile("file")` возвращает интерфейс `multipart.File` и метаданные `*multipart.FileHeader`.\n3. Сохранение осуществляется потоковым копированием через `io.Copy(dest, src)`.', 'step_by_step': '1. Создадим обработчик `uploadHandler`.\n2. Ограничим лимит 10 МБ.\n3. Откроем полученный файл и скопируем в целевой файл в папке `tempDir`.\n4. Протестируем загрузку через `multipart.Writer` на стороне клиента.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"mime/multipart"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"path/filepath"\n)\n\nfunc uploadHandler(w http.ResponseWriter, r *http.Request) {\n\tif r.Method != http.MethodPost {\n\t\thttp.Error(w, "Метод не поддерживается", http.StatusMethodNotAllowed)\n\t\treturn\n\t}\n\n\t// 10 МБ в памяти, остальное — во временные файлы\n\tif err := r.ParseMultipartForm(10 << 20); err != nil {\n\t\thttp.Error(w, "Ошибка разбора формы", http.StatusBadRequest)\n\t\treturn\n\t}\n\n\tfile, header, err := r.FormFile("avatar")\n\tif err != nil {\n\t\thttp.Error(w, "Поле \'avatar\' не найдено", http.StatusBadRequest)\n\t\treturn\n\t}\n\tdefer file.Close()\n\n\t// Сохраняем файл\n\toutPath := filepath.Join(os.TempDir(), "uploaded_"+header.Filename)\n\tdst, err := os.Create(outPath)\n\tif err != nil {\n\t\thttp.Error(w, "Не удалось сохранить файл", http.StatusInternalServerError)\n\t\treturn\n\t}\n\tdefer dst.Close()\n\n\twritten, _ := io.Copy(dst, file)\n\tdefer os.Remove(outPath)\n\n\tw.WriteHeader(http.StatusCreated)\n\tfmt.Fprintf(w, "Файл %s успешно сохранен (%d байт)", header.Filename, written)\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(uploadHandler))\n\tdefer ts.Close()\n\n\t// Клиентская отправка multipart формы\n\tbody := &bytes.Buffer{}\n\twriter := multipart.NewWriter(body)\n\tpart, _ := writer.CreateFormFile("avatar", "profile.png")\n\t_, _ = part.Write([]byte("fake png binary data"))\n\t_ = writer.Close()\n\n\treq, _ := http.NewRequest(http.MethodPost, ts.URL, body)\n\treq.Header.Set("Content-Type", writer.FormDataContentType())\n\n\tresp, _ := http.DefaultClient.Do(req)\n\trespBody, _ := io.ReadAll(resp.Body)\n\tresp.Body.Close()\n\n\tfmt.Printf("[Status] %d\\n", resp.StatusCode)\n\tfmt.Printf("[Response] %s\\n", string(respBody))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Status] 201\n# [Response] Файл profile.png успешно сохранен (20 байт)'}], 'under_the_hood': '`ParseMultipartForm` создает временные файлы с помощью `os.CreateTemp` в каталоге ОС, если размер файла превышает лимит оперативной памяти.', 'pitfalls': 'Всегда очищайте ресурсы формы вызовом `r.MultipartForm.RemoveAll()` после завершения обработки, чтобы удалить временные файлы с диска сервера.', 'bigtech_interview': '**Вопрос с собеседования:** «Как обработать загрузку файла размером 50 ГБ без исчерпания памяти и диска сервера?»\n**Ответ:** Не вызывать `ParseMultipartForm`. Использовать `r.MultipartReader()`, который построчно читает части формы потоком. При нахождении нужного part копировать его напрямую в S3 хранилище (`s3manager.Upload`) или внешнее хранилище через `io.Copy`.'}, {'num': 35, 'title': 'REST API управления списком задач (Task Tracker CRUD) на ServeMux', 'task': 'Создайте REST API для управления списком задач (in-memory): `GET /tasks`, `POST /tasks`, `GET /tasks/{id}`, `DELETE /tasks/{id}`. Используйте стандартный `http.ServeMux` с поддержкой методов.', 'theory': 'Проектирование чистых REST API коллекций:\n- `GET /tasks` — получить список задач.\n- `POST /tasks` — создать новую задачу.\n- `GET /tasks/{id}` — получить задачу по ID.\n- `DELETE /tasks/{id}` — удалить задачу.', 'step_by_step': '1. Опишем структуру `Task { ID, Title, Completed }`.\n2. Реализуем потокобезопасный `TaskStore`.\n3. Зарегистрируем маршруты в `http.NewServeMux()`.\n4. Протестируем создание, чтение и удаление задачи.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"encoding/json"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"strconv"\n\t"sync"\n)\n\ntype Task struct {\n\tID        int    `json:"id"`\n\tTitle     string `json:"title"`\n\tCompleted bool   `json:"completed"`\n}\n\ntype TaskManager struct {\n\tmu     sync.RWMutex\n\ttasks  map[int]Task\n\tnextID int\n}\n\nfunc NewTaskManager() *TaskManager {\n\treturn &TaskManager{tasks: make(map[int]Task), nextID: 1}\n}\n\nfunc (m *TaskManager) Add(title string) Task {\n\tm.mu.Lock()\n\tdefer m.mu.Unlock()\n\tt := Task{ID: m.nextID, Title: title, Completed: false}\n\tm.tasks[t.ID] = t\n\tm.nextID++\n\treturn t\n}\n\nfunc (m *TaskManager) List() []Task {\n\tm.mu.RLock()\n\tdefer m.mu.RUnlock()\n\tres := make([]Task, 0, len(m.tasks))\n\tfor _, t := range m.tasks {\n\t\tres = append(res, t)\n\t}\n\treturn res\n}\n\nfunc (m *TaskManager) Get(id int) (Task, bool) {\n\tm.mu.RLock()\n\tdefer m.mu.RUnlock()\n\tt, ok := m.tasks[id]\n\treturn t, ok\n}\n\nfunc (m *TaskManager) Delete(id int) bool {\n\tm.mu.Lock()\n\tdefer m.mu.Unlock()\n\tif _, ok := m.tasks[id]; !ok {\n\t\treturn false\n\t}\n\tdelete(m.tasks, id)\n\treturn true\n}\n\nfunc main() {\n\ttm := NewTaskManager()\n\tmux := http.NewServeMux()\n\n\tmux.HandleFunc("GET /tasks", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\t_ = json.NewEncoder(w).Encode(tm.List())\n\t})\n\n\tmux.HandleFunc("POST /tasks", func(w http.ResponseWriter, r *http.Request) {\n\t\tvar input struct {\n\t\t\tTitle string `json:"title"`\n\t\t}\n\t\tif err := json.NewDecoder(r.Body).Decode(&input); err != nil || input.Title == "" {\n\t\t\thttp.Error(w, "некорректный заголовок задачи", http.StatusBadRequest)\n\t\t\treturn\n\t\t}\n\t\tcreated := tm.Add(input.Title)\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\tw.WriteHeader(http.StatusCreated)\n\t\t_ = json.NewEncoder(w).Encode(created)\n\t})\n\n\tmux.HandleFunc("GET /tasks/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tid, _ := strconv.Atoi(r.PathValue("id"))\n\t\tt, ok := tm.Get(id)\n\t\tif !ok {\n\t\t\thttp.NotFound(w, r)\n\t\t\treturn\n\t\t}\n\t\tw.Header().Set("Content-Type", "application/json")\n\t\t_ = json.NewEncoder(w).Encode(t)\n\t})\n\n\tmux.HandleFunc("DELETE /tasks/{id}", func(w http.ResponseWriter, r *http.Request) {\n\t\tid, _ := strconv.Atoi(r.PathValue("id"))\n\t\tif !tm.Delete(id) {\n\t\t\thttp.NotFound(w, r)\n\t\t\treturn\n\t\t}\n\t\tw.WriteHeader(http.StatusNoContent)\n\t})\n\n\tts := httptest.NewServer(mux)\n\tdefer ts.Close()\n\n\t// 1. Создание задачи\n\tres1, _ := http.Post(ts.URL+"/tasks", "application/json", bytes.NewBufferString(`{"title":"Изучить роутинг Go 1.22"}`))\n\tb1, _ := io.ReadAll(res1.Body)\n\tres1.Body.Close()\n\tfmt.Printf("[Создано]  %s", string(b1))\n\n\t// 2. Получение списка\n\tres2, _ := http.Get(ts.URL + "/tasks")\n\tb2, _ := io.ReadAll(res2.Body)\n\tres2.Body.Close()\n\tfmt.Printf("[Список]   %s", string(b2))\n\n\t// 3. Удаление\n\treq, _ := http.NewRequest(http.MethodDelete, ts.URL+"/tasks/1", nil)\n\tres3, _ := http.DefaultClient.Do(req)\n\tres3.Body.Close()\n\tfmt.Printf("[Удаление] Status: %d (No Content)\\n", res3.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Создано]  {"id":1,"title":"Изучить роутинг Go 1.22","completed":false}\n# [Список]   [{"id":1,"title":"Изучить роутинг Go 1.22","completed":false}]\n# [Удаление] Status: 204 (No Content)'}], 'under_the_hood': 'Методы Go 1.22 маршрутизатора сопоставляются до парсинга параметров пути, обеспечивая максимальную скорость диспетчеризации.', 'pitfalls': 'Ответ 204 No Content по стандарту HTTP запрещает отправку тела ответа (`Content-Length: 0` или отсутствие тела).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему при возврате 201 Created хорошей практикой является установка заголовка Location?»\n**Ответ:** Заголовок `Location: /tasks/1` сообщает клиенту канонический URI вновь созданного ресурса, позволяя фронтенду или API-клиенту сразу перейти к созданному объекту без необходимости повторного поиска.'}, {'num': 36, 'title': 'Потоковая отдача больших файлов через io.Copy с O(1) расходом памяти', 'task': 'Напиши **streaming response**: handler читает большой файл и пишет его в `http.ResponseWriter` через `io.Copy`. Не загружай файл целиком в память. Добавь `Content-Type: application/octet-stream` и `Content-Disposition`.', 'theory': 'Потоковая отдача (Streaming I/O): передача данных чанками фиксированного размера (по 32 КБ) через `io.Copy(w, file)`. Память сервера расходуется в объеме $O(1)$ независимо от того, весит файл 10 МБ или 100 ГБ.', 'step_by_step': '1. Создадим тестовый файл размером 5 МБ.\n2. В обработчике откроем файл через `os.Open`.\n3. Установим `Content-Type: application/octet-stream`.\n4. Выполним потоковую передачу через `io.Copy(w, file)`.\n5. Проверим скачивание клиентом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"io"\n\t"net/http"\n\t"net/http/httptest"\n\t"os"\n\t"path/filepath"\n)\n\nfunc streamHandler(filePath string) http.HandlerFunc {\n\treturn func(w http.ResponseWriter, r *http.Request) {\n\t\tf, err := os.Open(filePath)\n\t\tif err != nil {\n\t\t\thttp.NotFound(w, r)\n\t\t\treturn\n\t\t}\n\t\tdefer f.Close()\n\n\t\tstat, _ := f.Stat()\n\t\tw.Header().Set("Content-Type", "application/octet-stream")\n\t\tw.Header().Set("Content-Disposition", fmt.Sprintf(`attachment; filename="%s"`, filepath.Base(filePath)))\n\t\tw.Header().Set("Content-Length", fmt.Sprintf("%d", stat.Size()))\n\n\t\t// Потоковая передача с фиксированным буфером 32КБ (Zero OOM risk!)\n\t\twritten, err := io.Copy(w, f)\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\t\t_ = written\n\t}\n}\n\nfunc main() {\n\ttmpFile, _ := os.CreateTemp("", "large_*.bin")\n\tfilePath := tmpFile.Name()\n\tdefer os.Remove(filePath)\n\n\t// Записываем 2 МБ тестовых данных\n\tchunk := bytes.Repeat([]byte("A"), 1024*1024*2)\n\t_, _ = tmpFile.Write(chunk)\n\t_ = tmpFile.Close()\n\n\tts := httptest.NewServer(streamHandler(filePath))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tdefer resp.Body.Close()\n\n\t// Читаем поток клиентом\n\tvar received bytes.Buffer\n\tn, _ := io.Copy(&received, resp.Body)\n\n\tfmt.Printf("[Stream Test] Успешно скачано: %.2f МБ (%d байт)\\n", float64(n)/(1024*1024), n)\n\tfmt.Printf("[Заголовки]   Content-Type: %s\\n", resp.Header.Get("Content-Type"))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Stream Test] Успешно скачано: 2.00 МБ (2097152 байт)\n# [Заголовки]   Content-Type: application/octet-stream'}], 'under_the_hood': '`io.Copy` перекачивает данные блоками. Если `w` поддерживает `io.ReaderFrom`, рантайм Go может задействовать оптимизацию Linux `sendfile(2)` для нулевого копирования данных в пользовательское пространство.', 'pitfalls': 'Если клиент внезапно разорвет соединение во время стриминга, `io.Copy` вернет ошибку `broken pipe` или `connection reset by peer`, которую не следует логировать как критическую ошибку сервера.', 'bigtech_interview': '**Вопрос с собеседования:** «Как системный вызов sendfile(2) ускоряет отдачу файлов по HTTP?»\n**Ответ:** `sendfile` копирует страницы данных напрямую из Page Cache диска в буфер сокета сетевой карты ядра Linux. Данные не копируются в память процесса Go и обратно, экономя такты CPU и полосу пропускания оперативной памяти.'}, {'num': 37, 'title': 'Server-Sent Events (SSE) с потоковым сбросом буфера через http.Flusher', 'task': 'Напиши **Server-Sent Events (SSE)**: handler с заголовком `Content-Type: text/event-stream`. В цикле отправляй `data: {"time": "..."}\\n\\n` каждую секунду. Используй `http.Flusher` для сброса буфера. Клиент — `curl` или браузер.', 'theory': 'Server-Sent Events (SSE) — протокол однонаправленного стриминга от сервера к браузеру поверх обычного HTTP/1.1 или HTTP/2:\n- Заголовок: `Content-Type: text/event-stream`.\n- Отключение буферизации: `Cache-Control: no-cache`.\n- Каждое сообщение форматируется как `data: <payload>\\n\\n`.\nИнтерфейс `http.Flusher` позволяет принудительно вытолкнуть накопленные в буфере байты в TCP-соединение клиенту.', 'step_by_step': '1. Проверим поддержку интерфейса `flusher, ok := w.(http.Flusher)`.\n2. Установим SSE-заголовки.\n3. В цикле отправим 3 события с паузой.\n4. После каждого события вызовем `flusher.Flush()`.\n5. Проверим получение потока клиентом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n\t"strings"\n\t"time"\n)\n\nfunc sseHandler(w http.ResponseWriter, r *http.Request) {\n\tflusher, ok := w.(http.Flusher)\n\tif !ok {\n\t\thttp.Error(w, "Стриминг не поддерживается", http.StatusInternalServerError)\n\t\treturn\n\t}\n\n\tw.Header().Set("Content-Type", "text/event-stream")\n\tw.Header().Set("Cache-Control", "no-cache")\n\tw.Header().Set("Connection", "keep-alive")\n\n\tfor i := 1; i <= 3; i++ {\n\t\teventData := fmt.Sprintf(`{"event_id": %d, "timestamp": "%s"}`, i, time.Now().Format(time.RFC3339))\n\t\tfmt.Fprintf(w, "data: %s\\n\\n", eventData)\n\t\tflusher.Flush() // Мгновенный сброс буфера клиенту!\n\t\ttime.Sleep(20 * time.Millisecond)\n\t}\n}\n\nfunc main() {\n\tts := httptest.NewServer(http.HandlerFunc(sseHandler))\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL)\n\tdefer resp.Body.Close()\n\n\tscanner := bufio.NewScanner(resp.Body)\n\tfor scanner.Scan() {\n\t\tline := scanner.Text()\n\t\tif strings.HasPrefix(line, "data:") {\n\t\t\tfmt.Printf("[SSE Event Received] %s\\n", line)\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [SSE Event Received] data: {"event_id": 1, "timestamp": "2026-09-03T13:48:00+04:00"}\n# [SSE Event Received] data: {"event_id": 2, "timestamp": "2026-09-03T13:48:00+04:00"}\n# [SSE Event Received] data: {"event_id": 3, "timestamp": "2026-09-03T13:48:00+04:00"}'}], 'under_the_hood': 'Стандартный `ResponseWriter` использует буфер размером 4 КБ. Без явного вызова `Flush()` данные не уйдут в сокет до тех пор, пока буфер не заполнится или хендлер не завершится.', 'pitfalls': 'В SSE цикле обязательно проверяйте `r.Context().Done()`: если пользователь закрыл вкладку браузера, цикл без проверки контекста превратится в вечную зомби-горутину.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда для real-time связи выбрать SSE, а когда WebSocket?»\n**Ответ:** SSE проще, работает поверх стандартного HTTP/1.1/HTTP/2, автоматически реконнектится браузером из коробки и идеален для однонаправленных потоков (ленты уведомлений, котировки, генерация LLM токенов). WebSocket нужен, когда требуется двунаправленный (full-duplex) обмен с ультранизкой задержкой (онлайн-игры, звонки, чаты).'}, {'num': 38, 'title': 'Архитектурные риски DefaultServeMux и запуск изолированного экземпляра', 'task': '**Мультиплексор (ServeMux)**: Использовать глобальный роутер (`nil` в `ListenAndServe`) — плохая практика (могут вклиниться сторонние пакеты). Создай `mux := http.NewServeMux()`. Зарегистрируй пути на нём и передай `mux` в `ListenAndServe`.', 'theory': 'Глобальное состояние — источник уязвимостей и сложноуловимых багов. `http.DefaultServeMux` является глобальной переменной пакета `net/http`. Любой сторонний пакет может неявно выполнить `http.HandleFunc("/debug/vars", ...)` при импорте через функцию `init()`.', 'step_by_step': '1. Создадим локальный `mux := http.NewServeMux()`.\n2. Зарегистрируем изолированные маршруты.\n3. Передадим `mux` в структуру `http.Server`.\n4. Проверим запуск.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc main() {\n\t// Явное создание изолированного роутера\n\tmux := http.NewServeMux()\n\n\tmux.HandleFunc("/api/v1/ping", func(w http.ResponseWriter, r *http.Request) {\n\t\tw.Header().Set("Content-Type", "text/plain")\n\t\tfmt.Fprint(w, "pong")\n\t})\n\n\tserver := &http.Server{\n\t\tHandler: mux, // Никакого nil!\n\t}\n\n\tts := httptest.NewServer(server.Handler)\n\tdefer ts.Close()\n\n\tres, _ := http.Get(ts.URL + "/api/v1/ping")\n\tdefer res.Body.Close()\n\n\tfmt.Printf("[Безопасный роутинг] Статус: %d\\n", res.StatusCode)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Безопасный роутинг] Статус: 200'}], 'under_the_hood': 'Когда в `http.Server{Handler: nil}` передается `nil`, метод `server.Serve` выполняет `handler := server.Handler; if handler == nil { handler = DefaultServeMux }`.', 'pitfalls': 'Случайный импорт `_ "net/http/pprof"` автоматически открывает профилировщик рантайма Go на `DefaultServeMux`. Если сервер использует глобальный роутер, отладочная информация утекает в сеть.', 'bigtech_interview': '**Вопрос с собеседования:** «Какую опасность несет импорт `_ "net/http/pprof"` при использовании http.DefaultServeMux?»\n**Ответ:** Пакет в `init()` регистрирует эндпоинты `/debug/pprof/*` в `DefaultServeMux`. Злоумышленник может скачать дампы памяти кучи (`heap`), стеки горутин (`goroutine`) с паролями и токенами или вызвать DoS профилированием CPU.'}, {'num': 39, 'title': 'Базовый шаблон логирующего Middleware на функции-обертке', 'task': 'Напиши простейший middleware-функцию: `func LoggingMiddleware(next http.Handler) http.Handler`. Она должна выводить в консоль метод и URL запроса, а затем вызывать `next.ServeHTTP(w, r)`.', 'theory': 'Базовый паттерн функции Middleware:\n```go\nfunc Middleware(next http.Handler) http.Handler {\n    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n        // До вызова\n        next.ServeHTTP(w, r)\n        // После вызова\n    })\n}\n```\nЭто простейший способ внедрения сквозной функциональности.', 'step_by_step': '1. Реализуем функцию `LoggingMiddleware`.\n2. В теле функции выведем `r.Method` и `r.URL.String()`.\n3. Делегируем вызов следующему обработчику `next.ServeHTTP(w, r)`.\n4. Проверим работу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net/http"\n\t"net/http/httptest"\n)\n\nfunc LoggingMiddleware(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Printf("[Incoming Request] Метод: %s, URL: %s, UserAgent: %s\\n",\n\t\t\tr.Method, r.URL.String(), r.UserAgent())\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/info", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Fprint(w, "Информация о системе")\n\t})\n\n\tloggedMux := LoggingMiddleware(mux)\n\tts := httptest.NewServer(loggedMux)\n\tdefer ts.Close()\n\n\tresp, _ := http.Get(ts.URL + "/info?debug=true")\n\tresp.Body.Close()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Incoming Request] Метод: GET, URL: /info?debug=true, UserAgent: Go-http-client/1.1'}], 'under_the_hood': 'Адаптер `http.HandlerFunc` оборачивает анонимную функцию в интерфейс `http.Handler` без необходимости создавать отдельную именованную структуру.', 'pitfalls': 'Не забывайте вызывать `next.ServeHTTP(w, r)`. Если вызов пропущен, цепочка оборвется и клиент зависнет или получит пустой ответ.', 'bigtech_interview': '**Вопрос с собеседования:** «Можно ли мутировать поля r *http.Request внутри Middleware?»\n**Ответ:** Прямая мутация полей указателя `*http.Request` не рекомендуется, так как запрос может параллельно обрабатываться или передаваться другим компонентам. Для изменения контекста создают копию через `r.WithContext(ctx)`, а для изменения URL — через `r.Clone(ctx)`.'}, {'num': 40, 'title': 'Плавная остановка сервера (Graceful Shutdown) с сигналом SIGINT и context.WithTimeout', 'task': 'Напиши **HTTP graceful shutdown**: `http.Server` + `srv.Shutdown(ctx)` с `context.WithTimeout(5s)`. При `SIGINT` — заверши текущие запросы, но не принимай новые. Используй `signal.NotifyContext`.', 'theory': 'Паттерн Graceful Shutdown (Мягкое завершение работы):\n1. Сервер прекращает слушать порт (новые соединения получают TCP RST или ошибку connect).\n2. Закрываются все неактивные сокеты в пуле Keep-Alive.\n3. Сервер дает активным запросам время завершить работу в пределах таймаута контекста `srv.Shutdown(ctx)`.\n4. Предотвращает обрыв транзакций и потерю пользовательских данных при деплое в Kubernetes.', 'step_by_step': '1. Создадим контекст с сигналом ОС `signal.NotifyContext(context.Background(), os.Interrupt)`.\n2. Запустим `srv.ListenAndServe()` в отдельной горутине.\n3. Дождемся сигнала остановки `<-ctx.Done()`.\n4. Вызовем `srv.Shutdown(shutdownCtx)` с дедлайном 5 секунд.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"net/http"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tmux := http.NewServeMux()\n\tmux.HandleFunc("/long-task", func(w http.ResponseWriter, r *http.Request) {\n\t\tfmt.Println(" [+] Начата долгая транзакция клиента (100 мс)...")\n\t\ttime.Sleep(100 * time.Millisecond)\n\t\tfmt.Fprint(w, "Транзакция успешно зафиксирована")\n\t\tfmt.Println(" [✓] Транзакция клиента завершена")\n\t})\n\n\tsrv := &http.Server{\n\t\tAddr:    "127.0.0.1:8999",\n\t\tHandler: mux,\n\t}\n\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\t// Запуск сервера в горутине\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfmt.Println("[Server] Запущен на http://127.0.0.1:8999")\n\t\tif err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {\n\t\t\tfmt.Printf("Ошибка сервера: %v\\n", err)\n\t\t}\n\t}()\n\n\ttime.Sleep(30 * time.Millisecond)\n\n\t// Запускаем клиента с долгой задачей в фоне\n\tgo func() {\n\t\tres, err := http.Get("http://127.0.0.1:8999/long-task")\n\t\tif err == nil {\n\t\t\tres.Body.Close()\n\t\t}\n\t}()\n\n\ttime.Sleep(20 * time.Millisecond)\n\n\t// Инициируем процедуру Graceful Shutdown\n\tfmt.Println("\\n[Signal] Получен сигнал SIGINT (Ctrl+C). Начинаем мягкую остановку...")\n\tshutdownCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)\n\tdefer cancel()\n\n\tif err := srv.Shutdown(shutdownCtx); err != nil {\n\t\tfmt.Printf("Ошибка принудительной остановки: %v\\n", err)\n\t} else {\n\t\tfmt.Println("[Server] Все активные запросы чисто доработали. Сервер остановлен штатно!")\n\t}\n\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server] Запущен на http://127.0.0.1:8999\n#  [+] Начата долгая транзакция клиента (100 мс)...\n# \n# [Signal] Получен сигнал SIGINT (Ctrl+C). Начинаем мягкую остановку...\n#  [✓] Транзакция клиента завершена\n# [Server] Все активные запросы чисто доработали. Сервер остановлен штатно!'}], 'under_the_hood': '`srv.Shutdown` сначала закрывает все слушающие сокеты `net.Listener`, затем переводит открытые соединения в режим завершения и ждет, пока счетчик активных соединений не станет равен нулю или не истечет контекст.', 'pitfalls': 'После вызова `srv.Shutdown` метод `ListenAndServe` немедленно возвращает ошибку `http.ErrServerClosed`. Ее необходимо игнорировать и не считать фатальным сбоем.', 'bigtech_interview': '**Вопрос с собеседования:** «Как Kubernetes останавливает Pod и почему Graceful Shutdown в Go критичен?»\n**Ответ:** K8s отправляет поду сигнал `SIGTERM` и ждет `terminationGracePeriodSeconds` (дефолт 30с) перед отправкой `SIGKILL`. Без `srv.Shutdown` сервер немедленно оборвет активные HTTP-сессии пользователей, а клиенты получат ошибку 502 Bad Gateway на Ingress.'}]
